quests[51903] = { id = 51903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inselexpedition", description = "Unsere Spione haben eine Nachricht der Horde abgefangen, in der eine Azeritablagerung im Großen Meer beschrieben wird.\n\nDie Erlösenden Winde ist nicht schnell genug, um uns vor ihnen dorthin zu bringen. Glücklicherweise habe ich dafür gesorgt, dass ein Schiff aus Kul Tiras aufgetakelt wird und für Gelegenheiten wie diese bereit steht.\n\nSprecht mit Käpt'n Finn Schönwind. Er weiß Bescheid und sollte Euch bereits erwarten.", sourceObjective = "Meldet Euch bei Finn Schönwind in Boralus.", completion = "Oh... Seid Ihr der {class}, der mir angekündigt wurde? Dann machen wir uns gleich an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[51904] = { id = 51904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inselexpedition", description = "Also, dann mal los! Wir müssen diese Insel schließlich vor der Horde erreichen, stimmt's?\n\nSeid Ihr bereit?", sourceObjective = "Sprecht mit Finn Schönwind, um die Expedition zu beginnen, und erkundet dann die Unerforschte Insel.", progress = "Ich bin bereit.", completion = "Ihr und ich, wir sind ein ziemlich gutes Gespann, nicht? Wir sollten das... äh... demnächst mal wieder machen.", sourceObjectiveStatus = "unverified-source-field" }
