quests[51916] = { id = 51916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vereinigung von Zandalar", description = "Die Zandalari sind ein vielfältiges und fähiges Volk. Wenn wir sie alle unter dem Banner der Horde vereinen könnten, hätte die Allianz keine Chance, uns aufzuhalten.", sourceObjective = "Erlangt mindestens einen freundlichen Ruf bei den Fraktionen von Zandalar.", completion = "Gut. Das Volk von Zandalar steht dank Euch nun auf unserer Seite, {name}.\n\nDie eigentliche Arbeit hat aber erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
