quests[51961] = { id = 51961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die andauernde Kampagne", description = "Wir haben in Sachen Zandalar hervorragende Fortschritte gemacht, {name}. Allerdings müssen wir unseren Einfluss weiter ausbauen.\n\nEs wird Zeit, ein weiteres Mal in See zu stechen und den Feind unter Druck zu setzen, um die Kontrolle der Horde über andere Länder einzudämmen.\n\nWelchen Ort sollen wir als Nächstes sichern?", sourceObjective = "Verwendet die Kampagnenkarte von Zandalar, um einen Stützpunkt auszuwählen.", completion = "Ausgezeichnete Wahl, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[51962] = { id = 51962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerholz frei Haus", description = "Das Hartholz im Dschungel is' so dicht, dass 'n geschickter Minenarbeiter damit fast so viel Hitze erzeug'n kann wie mit Kohle.\n\nDas größte Problem beim Benutz'n von einheimischem Holz is' aber, dass es im Dschungel immer feucht is'. Wenn das Holz nich' richtig gelagert wird, dauert es Wochen, bis es komplett getrocknet is'.\n\nIch erwähn das eben jetz', weil meiner Schmiede langsam der Brennstoff ausgeht.\n\nBringt mir trocknes Feuerholz, damit ich sie am Lauf'n halt'n kann, und ich zeig Euch 'nen Trick zum Abbau'n von Monelit.", sourceObjective = "Sammelt 9 Stücke trockenes Feuerholz.", progress = "Habt Ihr noch mehr Holz für mich?", completion = "Das sollte reich'n.\n\nAlso, dann spitzt ma' die Lauscher, denn ich verrat Euch jetz' Eure Belohnung. Wenn Ihr Monelit abbaut, haut es nich' einfach bloß aus dem Stein. Versucht stattdess'n, mit der Hacke das Metall aufzuspieß'n und es dann damit aus dem Stein zu zieh'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51963] = { id = 51963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorriks Zorn" }
quests[51964] = { id = 51964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerträgliche Blutsauger", description = "{name}! Ich hab da noch 'ne richtige Arbeit für Euch.\n\nWeil Eure Bergbaufertigkeiten nach Zandalarimaßstäben immer noch nich' annehmbar sind, zeig ich Euch zur Belohnung, wie Ihr Monelit besser abbau'n könnt.\n\nDie Bluttrolle von Nazmir halt'n sich diese riesigen Zecken als Haustiere, und ich hab gehört, die soll'n es bis an die Grenzen von Zuldazar im Norden geschafft ham. Das gefällt mir ganz und gar nich'.\n\nDezimiert die für mich 'n bisschen, damit mich stattdessen 'n Pterrordax oder 'n anderes respektables Viech fress'n kann.", sourceObjective = "Tötet 8 Blutbauchflügler und 8 Bluttrolle.", completion = "Reife Leistung, und Ihr seht nich' mal mitgenomm'n aus. Das werd ich mir fürs nächste Mal merk'n, wenn ich wieder jemanden brauch, der was für mich tötet.\n\nEuch is' ja sicher nich' aufgefall'n, dass sich Monelit hervorragend schmied'n lässt, oder? Sonst bräucht ich Euch ja wohl kaum diese Methode zeig'n. Ihr könnt Euch seine Formbarkeit aber schon vor dem Verhütt'n zunutze mach'n.\n\nIndem Ihr das Metall mit Eurer Hacke schon in der Ader verformt, könnt Ihr es anheiz'n und zusammen mit der anderen Technik, die ich Euch gezeigt hab, 'ne bessere Ausbeute erziel'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51965] = { id = 51965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine helfende Hand", description = "Falls Ihr Arbeit sucht, hätt ich da was für Euch.\n\nIch bin neulich schürf'n gewes'n, und dabei hat mir 'n Dimetrodon die Hand abgebiss'n, bevor ich mich vor dem rett'n konnt.\n\nDie Hand is' mir dabei egal... Die is' längst wieder nachgewachs'n. Allerdings hab ich dabei 'n paar Ringe verlor'n, die ich selber gefertigt hab.\n\nWenn Ihr mir die wieder zurückbringt, dann zeig ich Euch, wie Ihr mehr Monelit aus 'nem Flöz abbau'n könnt. Oder auch nich'. Mir egal. Aber falls Ihr auf 'ne Chance gewartet habt, mich endlich mal zu beeindruck'n, dann habt Ihr die vielleicht jetz'.", sourceObjective = "Holt Secotts Ringe zurück.", progress = "Damit das klar is': Diese Ringe sind wertvoller als Euer Leben... Rein erfahrungsgemäß gesproch'n.", completion = "<Secott schmückt seine neue Hand mit den Ringen.>\n\nGut! Als Goldschmied ohne Schmuck rumzulauf'n, das is' fast so, als wär man nackt.\n\nAlso gut. Der Inhalt von dieser Lektion is', dass sich das Monelit beim Abbau'n aus 'nem Flöz anders verhält als bei 'nem normalen Vorkommen.\n\n<Secott erklärt die verschiedenen Techniken zum Abbauen von Monelit so schnell, wie es nur irgend geht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[51967] = { id = 51967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Boralus", description = "Ich glaube, das war genug Aufregung für heute, <mein Junge/mein Mädchen>!\n\nVielleicht kehrt Ihr am besten zu Wyrmbann zurück und sagt ihm, dass wir hier alles unter Kontrolle haben.\n\nIch werde dafür sorgen, dass sich die Bluttrolle keine unserer Leute mehr holen! Ha!", sourceObjective = "Kehrt zu Halford Wyrmbann an Bord der Erlösenden Winde im Hafen von Boralus zurück. Desha Sturmschwelger kann Euch dorthin bringen.", completion = "Die Lande von Nazmir sind ein unwirtlicher Ort, aber die Siegesfeste wird jeder Gefahr trotzen.\n\nGut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[51968] = { id = 51968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Boralus", description = "Wisst Ihr, seit Eurer Ankunft in Zuldazar ist viel geschehen! Wyrmbann würde sich bestimmt über einen Bericht freuen.\n\nOh, aber nicht von mir. Vermutlich besser von einer etwas ernsthafteren Person... wie Ihr zum Beispiel!\n\nIch wette, Daria hier könnte Euch ziemlich schnell zurückbringen!", sourceObjective = "Kehrt zu Halford Wyrmbann an Bord der Erlösenden Winde zurück. Daria Schmidtke kann Euch dorthin bringen.", completion = "Wir starten unsere Missionen also von Xibala aus. Ich werde zusätzliche Verstärkungstruppen entsenden, um Brigadier Thom zu unterstützen.\n\nIch danke Euch für Euren Bericht, {name}. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[51969] = { id = 51969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Boralus", description = "Der Trümmersteinhafen ist eine weitläufige Stellung, die uns einen großen Vorteil gegenüber der Horde sichert.\n\nIch werde Umbric und den anderen das Kommando hier übertragen. Begeben wir uns an Bord der Erlösenden Winde und kehren nach Boralus zurück.", sourceObjective = "Kehrt zu Halford Wyrmbann an Bord der Erlösenden Winde in Boralus zurück.", completion = "Das Meer außerhalb von Vol'dun ist tückisch, aber Jes-Tereth ist eine der besten Steuerleute in diesen Gewässern!\n\nLasst uns den nächsten Sieg sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[51970] = { id = 51970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zuckerbäcker" }
quests[51971] = { id = 51971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine exquisite Brosche", description = "Ihr findet eine meisterhaft gefertigte blutige Brosche.\n\nDie exquisite Form und hervorragende Qualität des Stücks erinnern Euch an ein paar Ringe, die Ihr kürzlich für Secott wiederbeschafft habt.\n\nVielleicht hat er auch diesen Gegenstand verloren und hätte ihn gern zurück.", sourceObjective = "Bringt die exquisite Brosche zu Secott.\n\nBereitgestellter Gegenstand:", completion = "Boah, das is' ja 'ne richtig schicke Brosche. Das is' verdammt gute Arbeit.\n\nWem auch immer die vorher gehört hat, is'n Pechvogel, denn jetz' gehört die mir.\n\n<Secott bemerkt Euren missbilligenden Gesichtsausdruck und seufzt tief, begleitet von einem Augenrollen und einem leicht verächtlichen Blick.>\n\nWie wär's denn damit? Im Austausch gegen die Brosche verrat ich Euch alles, was es noch übers Abbau'n von Monelitflözen zu wiss'n gibt.\n\n<Secott erklärt Euch ausführlich mehrere Techniken, mit deren Hilfe Ihr Monelit effektiver aus Flözen abbauen könnt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[51972] = { id = 51972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verirrte Ziege" }
quests[51974] = { id = 51974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säbeltron" }
quests[51975] = { id = 51975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Schattenjäger Ty'jin", sourceObjective = "Beim Parley kann Euch keiner was vormach'n, Scheff. Bin echt beeindruckt.\n\nIch glaub, wir zwei sollt'n zusamm'bleib'n. Die Geister besteh'n drauf!\n\nKeine Angst, ich zieh mir was andres an.", sourceObjectiveStatus = "unverified-source-field" }
quests[51976] = { id = 51976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säbeltron" }
