quests[51979] = { id = 51979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die andauernde Kampagne", description = "Der Kriegshäuptling wünscht, dass wir unseren Einfluss in Kul Tiras weiter ausbreiten.\n\nDa sich unsere Kontrolle über Zandalar immer weiter festigt, ist es nun an der Zeit, unsere Ziele auch in den Ländern des Feindes aktiv zu verfolgen.\n\nWelchen Ort sollen wir als Nächstes sichern, {class}?", sourceObjective = "Verwendet die Kampagnenkarte von Kul Tiras, um einen Stützpunkt auszuwählen.", completion = "Ihr habt Eure Wahl getroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51980] = { id = 51980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Jabra'kan", description = "An alle Jäger, die einer Herausforderung würdig sind:\n\nFindet und besiegt den als Jabra'kan bekannten Troll. Durch seine Wilderei sind dem Kriegsbestienkral wertvolle Eier, Felle und Tiere für ihre Pferche verloren gegangen.\n\nHolt Euch Eure Belohnung bei Schwingenreiter Nivek ab.", sourceObjective = "Tötet Jabra'kan den Wilderer.", progress = "Wenn ich den diebischen Schuft seh, werd ich mir aus seinen Hauern 'ne Halskette mach'n. Is' es erledigt?", completion = "Vielen Dank. Dieser Wilderer is'n ziemlich schlüpfriger Bursche gewes'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51981] = { id = 51981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimstatt des Erdenrufers" }
quests[51982] = { id = 51982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wut des Sturms", description = "Streitkräfte der Horde rücken im Sturmsangtal immer weiter vor. Wir können diese Aggression nicht weiter dulden!", sourceObjective = "Schlagt die Streitkräfte der Horde zurück, die das Sturmsangtal angreifen.", completion = "Ihr habt den Leuten des Sturmsangtals und der Allianz heute gute Dienste geleistet. Ich danke Euch, {name}. Mit Beharrlichkeit werden wir die Horde aus diesem Land vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[51983] = { id = 51983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorriks Vergeltung" }
quests[51984] = { id = 51984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Zuldazar", description = "Schaut Euch das an, Zastamann! Wir ham die Piraten, 'n Ort nah der Hauptstadt von Kul Tiras...\n\nWir könn' da einigermaßen stolz drauf sein.\n\nWir sollt'n zu Nathanos zurückkehr'n un' ihm von unsrem Erfolg erzähl'n. Vielleicht lächelt der ja dann sogar mal.", sourceObjective = "Kehrt zu Nathanos Pestrufer auf die Klagelied zurück. Erul Dämmerbach kann Euch dorthin bringen.", completion = "Da hat Ty'jin einen schönen Standort geschaffen.\n\nUnd die Piraten sind auch von Vorteil. Wenn wir jemanden brauchen, der sich für uns opfert, sind sie perfekt geeignet...", sourceObjectiveStatus = "unverified-source-field" }
quests[51985] = { id = 51985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Zuldazar", description = "Ich glaube, wir haben hier alles unter Kontrolle. Meine Leute werden hier jede Menge Azerit finden und mich reich machen!\n\nAlso, ich meine natürlich die Horde reich machen... Und mächtig!\n\nAuf jeden Fall könnt Ihr Nathanos erzählen, dass hier alles erledigt ist. Von dieser Basis aus können wir die Kul Tiraner hier in Drustvar perfekt angreifen. Gallywix gibt sein Wort darauf!", sourceObjective = "Kehrt zu Nathanos Pestrufer auf die Klagelied zurück. Die Schwalldrescherin in Jederhafen kann Euch dorthin bringen.", completion = "Ihr habt mit den Goblins einen Stützpunkt in Drustvar gesichert? Gut.\n\nIch werde meinen Leuten sagen, dass sie Gallywix' Aktivitäten im Auge behalten sollen. Nur zur Sicherheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[51986] = { id = 51986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Zuldazar", description = "Die Reißzahnfeste ist unser am besten gesicherter Stützpunkt in Kul Tiras.\n\nKaga und ihre Einheiten werden dank Euch die Verstärkungen vornehmen können. Wir werden die Allianz überrollen!\n\nSagt Nathanos, dass unsere Mission ein Erfolg war. Ich werde hier solange helfen, wie man mich braucht.", sourceObjective = "Kehrt zu Nathanos Pestrufer auf die Klagelied zurück. Muka Sturmbrecher kann Euch dorthin bringen.", completion = "Die Reißzahnfeste ist eine wichtige strategische Basis für die Horde.\n\nSie muss unbedingt gesichert werden. Rexxar wird sich darum kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[51987] = { id = 51987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hobart Wurfhammer", sourceObjective = "Nun, da hier alles aufgebaut und eingerichtet ist, hab ich nichts mehr zu tun!\n\nIhr braucht doch bestimmt einen geschickten Ingenieur, oder? Warum nehmt Ihr mich nicht mit?", sourceObjectiveStatus = "unverified-source-field" }
quests[51988] = { id = 51988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitney \"Stahlklaue\" Ramsay" }
quests[51989] = { id = 51989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braedan Weißwall" }
quests[51990] = { id = 51990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwingen für den Kral", description = "Ich glaub, Euer Kleiner muss sich nach dem Abenteuer erst ma' ausruh'n. Ich werd gut drauf aufpass'n.\n\nFalls Ihr Euch nützlich mach'n wollt, während Ihr wartet, hätt ich da vielleicht was für Euch. Die Pterrordaxe im Nord'n soll'n in letzter Zeit richtig viele Eier leg'n. Zieht also los und sammelt die Eier ein, die sich beweg'n und aus denen Ihr Geräusche komm' hört. Da schlüpf'n die kleinen Biester nämlich bald aus.\n\nUnsere Tiere vermehr'n sich zwar gut, aber zusätzliche Flügel könn' wir im Kral immer gut gebrauch'n.", sourceObjective = "Sammelt 8 schlüpfbereite Pterrordaxeier.", progress = "Habt Ihr die Eier, die Ihr mir bring'n solltet?", completion = "Ich werd die dem Tierführer übergeb'n. Wenn wir sie behalt'n woll'n, müss'n wir das Erste sein, was die seh'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51991] = { id = 51991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Batterien aufladen", description = "Diese kleinen Kerlchen sind unersättliche Wirbelwinde verschlingender Zerstörung. Wenn sie erstmal loslegen, verleiben sie sich pausenlos alles ein, was ihnen in den Weg kommt! Wenn sie satt sind, geben sie Energieentladungen aus den kleinen elektrischen Antennen auf ihren Köpfen ab!\n\nDann machen sie ein Nickerchen.\n\nWir haben Glück, dass wir die richtige Frequenz gefunden haben, um ihre kleinen Käferhirne zu kontrollieren. Drückt auf das Gerät und Ihr könnt mit Eurem eigenen kleinen Britzler eine Runde drehen... im wahrsten Sinne des Wortes!\n\nSorgt dafür, dass Ihr ihn voll wieder zurückbringt, damit unser Zeug aufgeladen bleibt!", sourceObjective = "Füllt dem Ranishu den Bauch.", progress = "Na, alles aufgeladen?", completion = "He! Für Euer erstes Mal war das gar nicht schlecht! Die sind so hässlich, dass sie fast schon wieder süß sind, meint Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[51995] = { id = 51995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorriks Vergeltung" }
quests[51996] = { id = 51996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimstatt des Erdenrufers" }
quests[51997] = { id = 51997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da versinkt sie" }
quests[51998] = { id = 51998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WFT: Jetzt mit echtem Terrorhorn", description = "...Hört mal, {name}. Ich bräuchte da noch eine Sache, um mein Nahrungsergänzungsmittel fertigzustellen.\n\nIch kann das Wachstumshormon für Terrorhörner leider nicht ohne echtes Terrorhornfleisch herstellen. Mein Vorschlag, ein paar ihrer Tiere für meine Arbeit zu nutzen, wurde leider mit ein paar sehr spitzen Speeren abgewiesen.\n\nTja, und da habe ich mir eben eine andere Lösung ausgedacht.\n\nDiese fliegenden Bestien fressen doch Terrorhörner, nicht? Damit meine ich die großen grünen Flatterviecher. Wenn Ihr ein paar von denen tötet, findet Ihr bestimmt genug Terrorhornstücke für meine Arbeit.", sourceObjective = "Sammelt 8 Stück halb verdautes Terrorhornfleisch.", progress = "Das bleibt unter uns, einverstanden?", completion = "Verlieren wir nie wieder ein Wort darüber. Abgemacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[52003] = { id = 52003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kelsey Stahlfunken", sourceObjective = "Wisst Ihr, {name}, ich verfolge Euer Abenteuer jetzt schon seit einiger Zeit, und ich finde, Ihr seid einfach der Größte!\n\nIch hatte gehofft, ich könnte Euch vielleicht begleiten und Euch auf Euren Abenteuern helfen? Das Kämpfen beherrsche ich zwar nicht so gut, aber in Sachen Mechanik bin ich unschlagbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[52004] = { id = 52004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenspionage" }
quests[52005] = { id = 52005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Wolfsbau", description = "<Eure Anhänger haben Euch einen Bericht über einen Angriff auf den Wolfsbau geschickt.\n\nDarin wird erklärt, dass es ein schwer errungener Sieg war und dass alle bislang in dem Außenposten lebenden Banditen getötet wurden.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.>", sourceObjective = "Bringt den Bericht über Euren Sieg zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission zum Tiragardesund?", completion = "Die Mission, im Tiragardesund einen zusätzlichen Stützpunkt zu errichten, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52006] = { id = 52006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Präventivschlag" }
quests[52007] = { id = 52007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmaschinen" }
quests[52008] = { id = 52008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Magister Umbric", sourceObjective = "Ich weiß manchmal wirklich nicht, wie ich in solche Situationen gerate!\n\nErstens gibt es hier rein gar nichts, das mich interessiert, und zweitens ist diese Bruthitze kaum zu ertragen. Ich hätte es ja verstanden, wenn man mich mit der Untersuchung des Steins dieses Sethraks beauftragt hätte... Aber dem ist leider nicht so.\n\nWürdet Ihr mich bitte hier rausbringen, damit ich wieder etwas von Bedeutung tun und etwas bewirken kann?", sourceObjectiveStatus = "unverified-source-field" }
quests[52009] = { id = 52009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krabbenvolk", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52010] = { id = 52010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flut des Schicksals" }
quests[52011] = { id = 52011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Felder" }
quests[52012] = { id = 52012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wölfe für den Bau", description = "Unsere Späher haben ein großes Rudel Terrorwölfe nicht weit von hier entdeckt. Das ist ein gutes Zeichen!\n\nWir sollten einen Meister der Tiere hinschicken, um das Rudel einzufangen und zum Außenposten zu bringen, damit die Wölfe dort gezähmt werden.\n\nDie Terrorwölfe sind großartige Jagdbegleiter und spüren alle Allianzspione auf, die hier herumschnüffeln!", sourceObjective = "Schließt die Mission \"Wölfe für den Bau\" ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[52013] = { id = 52013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: John J. Keeshan", sourceObjective = "Da wir hier nun richtig Fuß gefasst haben, möchte ich mich größeren Zielen zuwenden.\n\nIhr habt Euch um Conrad gekümmert. Ihr habt Euch um die Bluttrolle gekümmert. Was wohl als Nächstes kommt?\n\nNun, was immer es auch ist, ich bin dabei. Ihr werdet einen hartgesottenen, erfahrenen und zähen Kämpfer wie mich brauchen, wenn Ihr diesen Krieg gewinnen wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[52014] = { id = 52014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituelle Vorbereitungen", description = "Ich hab da 'ne Anfrage für 'ne Ladung Sturmsilber gekriegt. Das is'n edles Metall, leicht und korrosionsbeständig. Wir benutz'n das überall auf unsren Schiffen. Es is' sogar so stark, dass es die Naga beim Herstell'n einiger ihrer Waffen verwend'n!\n\nDie Teile, die für Schiffe benutzt werd'n, müss'n vorher aber von 'nem Wellensänger gesegnet werd'n. Für so 'nen Blödsinn hab ich aber keine Zeit. Ich glaub nämlich nich', dass man das Metall unbedingt segnen muss, aber was weiß ich schon?\n\nBesorgt mir 'nen Eimer voll Erz und lasst es segnen, dann bring ich Euch bei, wie Ihr es leichter abbau'n könnt.", sourceObjective = "Baut ungeweihtes Sturmsilbererz ab, verhüttet es zu ungeweihten Sturmsilberbarren und lasst die Barren dann von Wellensänger De'zan segnen.", completion = "Die seh'n richtig gut aus. Da merkt bestimmt keiner, dass ich die nich' selber besorgt hab.\n\nDie Barren werd'n für unser nächstes Kriegsschiff gebraucht. Vorher müss'n die aber noch vergoldet werd'n.\n\nWas? Ihr habt doch nich' wirklich gedacht, die Ornamente wär'n aus reinem Gold, oder? Ha! Dann würd'n die ja Tonnen wieg'n!\n\nAber gut, eine Hand wäscht die andre, und ich werd jetz' Eure wasch'n. Sturmsilber is' von Natur aus sehr brüchig. Es is' also besser, wenn Ihr beim Abbau'n mehrmals vorsichtig zuschlagt, als einmal richtig hart. Dann wird das Metall auch nich' splittern.", sourceObjectiveStatus = "unverified-source-field" }
quests[52015] = { id = 52015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesalzene Gerechtigkeit", description = "{name}, ich hab gerade gehört, dass eines unsrer Schiffe angegriff'n word'n is' und 'ne große Menge Sturmsilber geklaut wurde!\n\nDieses geweihte Material lässt sich nich' ersetz'n. Wenn es vom Wellensänger gesegnet word'n is', wird es ein Jahr lang unter Wasser gelagert! Ich halt von dem Unsinn zwar nix, aber andre Leute glaub'n da fest dran, und genau die fahr'n auch auf dem Schiff.\n\nIch hab gehört, dass 'ne Gruppe Naga dem Schiff gefolgt is'. Die ham erst beobachtet, wo das Metall auf den Meeresgrund versenkt word'n is', um dann die Mannschaft zu töt'n und sich die Fracht unter den Nagel zu reiß'n.\n\nTötet die Naga und besorgt mir das Metall.", sourceObjective = "Beschafft 100 gestohlene Sturmsilberbarren.", progress = "Da soll der Loa doch die Naga verdamm'n!\n\nHabt Ihr die Barren gefund'n?", completion = "Ah, das sind ja super Neuigkeiten! Ich lass das gleich jemand zu den Docks bring'n.\n\nIch hatt schon befürchtet, dass Ihr das nich' schafft. An sich wär das ja nich' schlimm gewes'n, aber ich erklär mich eben nich' gern zweimal.\n\nAber Ihr habt meine Leute gerächt, und dafür werd ich Euch jetz' in die Feinheiten beim Abbau'n von Sturmsilber einweih'n.\n\n<Während der nächsten Minuten erklärt Euch Secott, was er über den Abbau von Sturmsilbervorkommen weiß.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52016] = { id = 52016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voll bis Oberkante Unterlippe", description = "Ihr wollt mehr über Sturmsilber erfahr'n?\n\nNa schön... Wenn Ihr 'n Flöz abbaut und 'nen Fehler macht, kann dabei 'ne tödliche Wolke aus pulverisiertem Material entsteh'n. Und jetz' geht.\n\n<Nach einem Moment entspannen sich die Gesichtszüge von Secott.>\n\nIch hab echt viel zu tun, aber wenn Ihr echt nich' sterb'n wollt, dann sprecht mit meinem ehemalig'n Lehrling, Biru. Das is' einer von den Trinkern im Geister mit Euch, aber er weiß 'ne ganze Menge.\n\nSprecht mit Ximo dem Wirt und kauft ihm 'n Getränk. Wenn's ihm schmeckt, wird er mit Euch red'n. Falls nicht... nun ja, ich hoff, Ihr habt genug Kleingeld für 'n paar Runden.", sourceObjective = "Bringt Biru dem Säufer ein Getränk, das er mag, damit er Euch seine Bergbaugeheimnisse verrät.", progress = "<Secotts einstiger Lehrling Biru starrt Euch mit trunkenen Augen an.>\n\nWash wollt'n Ihr?", completion = "<In wirren Worten versucht Biru, Euch die Techniken zum Abbau von Sturmsilber aus einem Flöz zu erklären.>\n\n... un' so kriegt Ihr... das meiste aus 'nem Flöz raus... Zzz...\n\n<Als Biru in einer penetranten Dunstwolke aus Branntwein wieder langsam in seine Traumwelt abgleitet, denkt Ihr an den Ratschlag, den er Euch gab.\n\nIhr wollt dieses neue Abbauverfahren unbedingt ausprobieren und lasst den schlafenden Troll einfach da liegen, wo er gerade ist.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52017] = { id = 52017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Biru", description = "Oh, Ihr seid immer noch da?\n\nTja, ich würd Euch ja wirklich gern helf'n, aber als einziger Goldschmied in der Gold'nen Stadt hab ich erstaunlich viel zu tun.\n\nIch hab gehört, Ihr habt Euch mit Biru angefreundet? Der erinnert sich bestimmt noch an mehr, falls Ihr noch mehr lern' wollt.\n\nFragt ihn, ob er Euch noch was beibring'n kann, und sagt ihm, dass ich aufhör'n werd, tollkühne Bergarbeiter zu ihm zu schick'n, wenn er weiter dafür sorgt, dass Ihr mich heut nich' mehr stört.", sourceObjective = "Sprecht mit Biru dem Säufer.", completion = "Secott schickt Euch?\n\nMoment ma... Mein alter Meister? DER Secott?", sourceObjectiveStatus = "unverified-source-field" }
quests[52023] = { id = 52023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde informieren", description = "General Jakra'zet wurde bezwung'n, doch seine Beschwörung von Mythrax is' trotz unsrer Mühen gelung'n.\n\nWenn Sethraliss uns nich' beigestand'n hätte, wär'n wir sicher nich' lebendig aus Atul'Aman rausgekomm'.\n\nWir müss'n unsre Verbündeten wiss'n lass'n, was in Vol'dun passiert is'.\n\nIch selbst werd mit Prinzessin Talanji sprech'n. Ihr solltet die Horde informier'n. Wir brauch'n so viel Hilfe wie möglich.\n\nIch bin sicher, wir werd'n uns erneut treff'n, {name}. War mir eine Ehre, an Eurer Seite zu kämpf'n.", sourceObjective = "Sprecht mit Baine Bluthuf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52024] = { id = 52024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde informieren", description = "General Jakra'zet wurde bezwung'n, doch seine Beschwörung von Mythrax is' trotz unsrer Mühen gelung'n.\n\nWenn Sethraliss uns nich' beigestand'n hätte, wär'n wir sicher nich' lebendig aus Atul'Aman rausgekomm'.\n\nWir müss'n unsre Verbündeten wiss'n lass'n, was in Vol'dun passiert is'.\n\nIch selbst werd mit Prinzessin Talanji sprech'n. Ihr solltet die Horde informier'n. Wir brauch'n so viel Hilfe wie möglich.\n\nIch bin sicher, wir werd'n uns erneut treff'n, {name}. War mir eine Ehre, an Eurer Seite zu kämpf'n.", sourceObjective = "Sprecht mit Baine Bluthuf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52026] = { id = 52026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attentat in Übersee", description = "Seid Ihr bereit, in den Krieg zu ziehen, {name}?\n\nMathias Shaw hat eine Liste mit Prioritätszielen der Horde zusammengestellt. Beim ersten Ziel handelt es sich um einen einflussreichen Blutelfen namens Arlethal Sonnenwächter. Unseren Informationen zufolge ist er ein hochrangiges Mitglied der Archäologischen Akademie, einer Eliteausgrabungseinheit der Blutelfen.\n\nIm Moment hält er sich mitten in der Wüste von Vol'dun auf. Das kommt quasi einer Einladung gleich, ihn umzubringen. Seid Ihr bereit?", sourceObjective = "Sprecht mit Großadmiralin Jes-Tereth, um nach Vol'dun zu reisen.", completion = "Da wären wir. Lasst uns die Sache angehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52027] = { id = 52027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plan für Vol'dun", description = "Unser Ziel: Arlethal Sonnenwächter, Oberster Prüfer der Archäologischen Akademie.\n\nWir sollten uns nicht blindlings in die Dünen stürzen. Daher halte ich eine kurze strategische Besprechung mit Euch und den anderen für angebracht.", sourceObjective = "Besprecht das strategische Vorgehen mit Halford Wyrmbann und Shandris Mondfeder.", progress = "Wir müssen uns über die Strategie unterhalten, {name}.", completion = "Ich bewundere Shandris'... Direktheit.\n\nWir werden mit beiden Plänen fortfahren. Los geht's.", sourceObjectiveStatus = "unverified-source-field" }
quests[52028] = { id = 52028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchkämmt die Wüste", description = "Dann wird es Zeit, dass wir aktiv werden.\n\nIch werde bei Euch bleiben, {name}. Haltet nach Aktivitäten der Horde Ausschau.", sourceObjective = "Sucht in Vol'dun nach Anzeichen auf Aktivitäten der Horde.", completion = "Ich glaube nicht, dass sie uns schon entdeckt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[52029] = { id = 52029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzige Arbeit", description = "Diese Feldmesserin trägt einen Wappenrock der Archäologischen Akademie. Sonnenwächter scheint Goblins anzuheuern, um sie die Drecksarbeit erledigen zu lassen, während er es sich irgendwo im Hintergrund gemütlich macht.\n\n<Shandris legt einen Pfeil auf ihren Bogen.>\n\nDann lasst uns herausfinden, was sie weiß.", sourceObjective = "Tötet Nazlara und findet heraus, was sie weiß.", progress = "Was führt dieser Goblin im Schilde?", completion = "<Halford inspiziert das Dokument der Archäologischen Akademie, das Ihr besorgt habt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52030] = { id = 52030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterkämmen", description = "Guzbert wird eine Weile damit beschäftigt sein, die Sprengladungen zu platzieren. Wir sollten Richtung Süden gehen, um nach weiteren Anzeichen auf Aktivitäten der Horde zu suchen.", sourceObjective = "Sucht nach weiteren Spuren der Horde.", completion = "Da oben, bei den Ruinen. Seht Ihr sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[52031] = { id = 52031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klassische Archäologie", description = "Ein weiterer Goblinfeldmesser. Und er scheint einer Art Aufseherin der Blutelfen zu unterstehen. Wir kommen unserem Ziel immer näher, {name}.\n\nIhr wisst ja, was zu tun ist.", sourceObjective = "Helft Shandris, Elisa Schleiersang und Daxx Bombenhand zu töten, und findet heraus, was sie wissen.", progress = "Sonnenwächter wird bald uns gehören.", completion = "Eine Karte. Perfekt! Damit sollten wir alle benötigten Informationen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[52032] = { id = 52032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hört niemals auf zu kämmen", description = "<Halford schaut sich ein letztes Mal die Karte an und faltet sie dann zusammen.>\n\nAlso dann, weiter nach Süden!", sourceObjective = "Sucht weiter nach Spuren der Horde.", completion = "Uns bietet sich hier eine Gelegenheit, {name}. Es wäre eine Schande, sie nicht zu nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52033] = { id = 52033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Die Frostjägerin", description = "Die Kronsteigwache bietet eine Belohnung für jeden Jäger, dem es gelingt, die Frostjägerin in der Umgebung des Hochwegpasses aufzuspüren und sie zu eliminieren.\n\nBei der Verfolgung ist größte Vorsicht geboten. Sie ist eine wilde Bestie, die schon erfahrene Jäger in den Hinterhalt gelockt hat.", sourceObjective = "Besiegt die Frostjägerin in der Nähe des Hochwegpasses.", completion = "Es ist also endlich jemandem gelungen, die Frostjägerin aufzuspüren? Dann können unsere Händler jetzt endlich weiter nach Tiragarde reisen, ohne diese Bestie fürchten zu müssen.\n\nHier habt Ihr Eure Belohnung. Und vielen Dank auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[52034] = { id = 52034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Botschaft an die Zandalari", description = "Ich weiß, wir sind hier, um die Horde zu jagen, aber uns bietet sich eine Gelegenheit.\n\nVerbannte oder nicht, das sind Zandalaritrolle, und die Zandalari haben sich mit der Horde zusammengetan.\n\nZeigen wir ihnen, was wir mit Freunden\nder Horde machen.", sourceObjective = "Tötet 12 Verbannte der Zandalari.", completion = "Ich hoffe, Ihr habt ein paar am Leben gelassen.\n\nSie müssen lernen, uns zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[52035] = { id = 52035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improvisierte Überlebenskunst", description = "Der gesamte Stauraum unseres Kopters war für Bomben reserviert und es sind sogar tatsächlich noch ein paar davon übrig. Leider konnten wir deshalb aber nicht genug Wasser und Verpflegung einpacken, um hier draußen zu überleben.\n\nDie Wüstenbewohner sind sehr effizient, was das Horten von Vorräten angeht. Ich bin mir sicher, dass die Zandalaritrolle da vorne ein paar verlorene Vorräte bestimmt nicht vermissen würden.", sourceObjective = "Sammelt 15 Zandalariwasserkrüge und 15 Zandalarirationen.", progress = "<Halford nickt Euch streng zu.>", completion = "Hervorragende Aufklärungsarbeit.\n\n<Halford beginnt mit der Verteilung des Wassers und der Rationen an die anderen Mitglieder Eurer Gruppe.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52036] = { id = 52036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben hier Alpakas", description = "Habt Ihr das gesehen? Habt Ihr sie gesehen? Die flauschigen Alpakas?!\n\nICH WOLLTE SCHON IMMER EIN... Ich meine, äh, ähem! Ich würde gerne ein Alpaka besitzen. Für Studienzwecke. Aus wissenschaftlichen Gründen. Hat gar nichts mit der Flauschigkeit zu tun.\n\nHier, das sollte Euch helfen, eins hierherzubekommen.", sourceObjective = "Verwendet das ultrasichere elektrische Alpakalasso, um ein verirrtes Alpaka einzufangen, und bringt es dann zu Explosionist Robolöt.", progress = "So... flauschig...", completion = "Ist die süß. Seht sie Euch an!\n\nSEHT SIE EUCH DOCH AN.", sourceObjectiveStatus = "unverified-source-field" }
quests[52038] = { id = 52038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufteilen", description = "<Halford lässt seinen Blick wieder über die Karte schweifen.>\n\nDie letzte Ausgrabungsstätte der Archäologischen Akademie befindet sich südwestlich von hier.\n\n{name}, Ihr und Shandris seid dafür verantwortlich, dass die Sprengladungen an der Ausgrabungsstätte platziert werden. Ich arbeite mit Robolöt daran, eine sichere Position zu finden, von der aus man sie auslösen kann.", sourceObjective = "Reist weiter südwestlich durch die Wüste.", completion = "<Shandris leckt sich erwartungsvoll die Lippen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52039] = { id = 52039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verspätete Todifizierung", description = "Den Anschlag können wir allein bewältigen, aber ich denke, es kann nicht schaden, diese gnomischen Bomben an der Ausgrabungsstätte des Gegners zu verteilen.\n\nSie können aus der Ferne gezündet werden, also versucht, sie im Sand zu vergraben, wo sie nicht bemerkt werden.", sourceObjective = "Vergrabt 8 ferngezündete Todesbomben.", completion = "Erledigt? Gut. Beeilen wir uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[52040] = { id = 52040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Pfeilen durchlöchert", description = "Halfords übermäßig komplizierte Wüstenexplosionsoperation ist vollkommen überflüssig. Wir können uns hier und jetzt um Arlethal Sonnenwächter kümmern.\n\nEr ist gleich da drüben. Wir können ihn einfach... töten.\n\nIhr greift ihn an. Ich stoße dazu, wenn er\nes am wenigsten erwartet. Seid Ihr bereit?", sourceObjective = "Tötet Arlethal Sonnenwächter mit Shandris.", completion = "Halford ist bestimmt froh, wenn er herausfindet, dass wir ihm die Arbeit abgenommen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[52041] = { id = 52041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Wyrmbann melden", description = "Wir sind hier fertig. Halford und Robolöt sollten weiter unten an der Küste im Osten sein.\n\nWenn es Euch nichts ausmacht, treffen wir uns dort.", sourceObjective = "Meldet Euch bei Halford Wyrmbann in Vol'dun.", completion = "Arlethal ist bereits tot?\n\nDas ist gut, nehme ich an... Obwohl es meinem Plan den Spaßfaktor nimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52042] = { id = 52042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Knall", description = "Dennoch, wir haben all diese Sprengladungen angebracht und uns hindert nichts daran, sie detonieren zu lassen und die Ausgrabungen der Horde\nin Schutt und Asche zu legen.\n\nSprecht mit Robolöt, wenn Ihr so weit seid, und wir setzen diese explosive Gnomentechnologie in Gang!", sourceObjective = "Sprecht mit Explosionist Robolöt, um das Vol'dunexplosionsprotokoll einzuleiten.", progress = "Bereit, wenn Ihr es seid.", completion = "Ha ha! Das sollte die Archäologische Akademie ein paar Monate kosten.", sourceObjectiveStatus = "unverified-source-field" }
quests[52043] = { id = 52043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache der Weintrauben", description = "Ihr kommt mir bekannt vor. Schuldet Ihr mir Geld? Halt, Moment... das isses nich'.\n\nWenn Ihr hier seid, weil Ihr was lern' wollt, kann ich Euch meine geheime Bergbaumethode zeig'n, aber... Ächz...\n\nIch bin im Moment hauptsächlich damit beschäftigt, den Kopf klar zu krieg'n. Ächz... Ich fühl mich, als würd mir jemand den Schädel mit 'ner Spitzhacke einschlag'n. \n\nDas beste Mittel gegen so 'nen Kater is' Einmachessig un' 'n großes deftiges Frühstück.\n\nWie wär's denn damit? Ihr bringt mir so schnell un' leise wie möglich so 'n Frühstück, un' ich bring Euch bei, was immer Ihr wiss'n wollt.", sourceObjective = "Bringt Biru dem Säufer ein Glas Einmachessig, einen Berg Speck, einen Stapel Würste und einen Haufen Eier.", progress = "Die Schatten sin' so laut. Könnt Ihr da nich' auch was gegen mach'n?", completion = "Genau das hab ich gebraucht!\n\n<Biru schaufelt sich das Essen in den Mund.>\n\nMmm... Also gut! Wenn ich mich nich' täusch, dann habt Ihr nach Sturmsilberflözen gefragt?\n\nAlso, dann werd ich Euch jetz' meine Geheimtechnik verrat'n, die nich' mal Secott kennt. Wenn Kräfte von außen auf das Metall wirk'n, kann es schnell brech'n. Anstatt das Metall an der Nahtstelle zum Felsen abzutrenn', is' es daher besser, gleich den ganz'n Stein zu entfern'.\n\nDas Metall bildet natürliche Prismen un' lässt sich ganz leicht ausm Stein zieh'n, wenn alles erst mal gelockert is'. So geht auch nix davon verlor'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[52044] = { id = 52044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein außergewöhnlicher Platinbrocken", description = "Mit viel Glück ist es Euch gelungen, anstatt mehrerer kleiner Stücke einen großen Brocken Platin abzubauen.\n\nIhr fragt Euch, ob Ihr mit Mirtes Hilfe vielleicht regelmäßig eine solche Ausbeute erzielen könntet.", sourceObjective = "Bringt den außergewöhnlichen Platinbrocken zu Mirte Krebeck.\n\nBereitgestellter Gegenstand:", completion = "Hui, da habt Ihr ja wirklich einen ordentlichen Brocken Platin erwischt. Ich bin beeindruckt!\n\nMir scheint, es ist Euch gelungen, das Erz genau in Richtung der Schicht zu treffen. Das ist in etwa so, wie wenn Ihr beim Holzspalten in Richtung der Maserung schlagt, anstatt gegen die Maserung.\n\nWenn Ihr beim Schlagen mit der Hacke auf etwas Kraft verzichten würdet und dafür präziser zu Werke gingt, um in Schichtrichtung zu schlagen, dann könntet Ihr vermutlich immer derart große Brocken abbauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[52045] = { id = 52045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberpatrouille" }
quests[52046] = { id = 52046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein außergewöhnlicher Platinbrocken", description = "Mit viel Glück ist es Euch gelungen, anstatt mehrerer kleiner Stücke einen großen Brocken Platin abzubauen.\n\nIhr fragt Euch, ob Ihr mit Secotts Hilfe vielleicht regelmäßig eine solche Ausbeute erzielen könntet.", sourceObjective = "Bringt den außergewöhnlichen Platinbrocken zu Goldschmied Secott.\n\nBereitgestellter Gegenstand:", completion = "Hey, wenn das nich' beeindruckend is'! Ein hübscher Brock'n Platin, und das in einem Stück.\n\nIch darf wohl annehm', dass das Zufall war, was?\n\nUm uns beiden Zeit zu spar'n, erzähl ich Euch alles, was ich über Platin weiß. Wenn Ihr mehr wiss'n wollt, fragt jemand andres.\n\nDas Erz bildet sich in Schicht'n, ähnlich wie die Ringe eines Baumstamms. Richtet Eure Hacke nach den Schicht'n aus, wenn Ihr zuhackt, und die Brocken bleib'n intakt, anstatt auseinanderzubrech'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[52047] = { id = 52047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen den Sturm" }
quests[52049] = { id = 52049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kreuz mit dem Erz", description = "Ihr findet ein gefaltetes Stück altes Papier bei dem Vorkommen.\n\nIhr faltet es auseinander und findet eine Karte von Drustvar mit einem Kreuz, das einen Ort an der Westküste markiert.\n\nMehrere unbeholfene Gedichte zieren das Papier, von denen ganz besonders eines Eure Aufmerksamkeit weckt.\n\n\"Einst frönte ich dem Piratenleben\nund kannte nur Wein, Weib und Gesang.\nNach der Meuterei hab ich es aufgegeben,\nund grab nun nach Schätzen tagelang.\"\n\nWer immer dies hinterlassen hat, scheint lange Zeit hierzulande Bergbau betrieben zu haben und hat dabei womöglich ein paar Erkenntnisse gewonnen, von denen auch Ihr profitieren könntet.", sourceObjective = "Findet den Urheber der zerfledderten Karte in Drustvar.\n\nBereitgestellter Gegenstand:", completion = "<Beim Anblick der Karte lässt Zunderlunt die Waffe sinken.>\n\nWie ich sehe, habt Ihr meine Karte gefunden. Dann seid Ihr wohl auch im Bergbau tätig, was?\n\nAlso, wenn nach Schätzen graben wollt, könnt Ihr in der Nase bohren. Aber wenn Ihr Arbeit wollt, hätte ich was für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[52050] = { id = 52050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine anspruchsvollere Karriere", description = "Wie Ihr Euch denken könnt, liegt mir das Piratendasein im Blut. Hab viele der besten Jahre meines Lebens mit plündern und brandschatzen zugebracht.\n\nDer Höhepunkt aber war immer, eine Truhe vollgepackt mit Gold und Juwelen an einem Ort zu vergraben, den nur ich kenne.\n\nAber so ein Leben wär heutzutage nichts mehr für mich. Das Säbelrasseln macht mich müde und vom Grog wird mir nur schlecht. Aber... Schätze kann ich trotzdem noch vergraben.\n\nBringt mir Beute, die es wert ist, vergraben zu werden, und ich werde Euch alles verklickern, was ich über die Jahre über den Bergbau gelernt hab.\n\nNa, wie wär's? Wollt Ihr <mein Pirat/meine Piratin> sein?", sourceObjective = "Sammelt 20 Platinbrocken.", progress = "Die Winde stehen gut für ein Abenteuer!", completion = "Wenn das mal keine fette Beute ist! Zieht Euch eine Kiste ran und schnappt Euch einen Krug Rum! Das wird eine lange Geschichte!\n\n<Ein Rum folgt auf den anderen, während Zunderlunt so manche humorvolle und informative Anekdote zum Besten gibt, darunter sogar ein paar, bei denen es um den Abbau von Platin geht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52051] = { id = 52051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Raid Finder - 1st" }
quests[52052] = { id = 52052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Raid Finder - Nth" }
quests[52053] = { id = 52053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Platinkarte", description = "Tief eingebettet in die Spalten des Vorkommens findet Ihr eine kleine Scheibe reinen Platins.\n\nAls Ihr den Staub abklopft, seht Ihr, dass Gravuren die Oberfläche verzieren, die Ihr als Karte von Vol'dun erkennt. Ihr bemerkt, dass im Südwesten etwas eingekreist wurde, das nach einer kleinen Höhle aussieht.\n\nWer immer dies hinterlassen hat, scheint allerhand über das Metall zu wissen und will offenbar gefunden werden.", sourceObjective = "Findet den Urheber der Platinkarte in Vol'dun.\n\nBereitgestellter Gegenstand:", completion = "Schön, Euch kennenzulernen. Mein Name is' Ta'mil. Setzt Euch doch. Wir ham viel zu besprech'n.\n\nVor langer Zeit war ich mal 'n Minenarbeiter und Schamane.\n\nIch hab den Geistern gesagt, welche Metalle ich brauch und warum, und hab sie um das Zeug gebet'n, was imma sie übrig hatt'n. Sie brachten mir dann nach ob'n, was immer sie konnt'n.\n\n<Sein Ton wird kälter und seine Miene verdüstert sich.>\n\nJetzt sag'n mir die Geister, dass ich nich' mehr lang auf dieser Welt hab. Selbst hier in der Wüste spür ich die Kälte bis in die Knoch'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[52054] = { id = 52054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saubäre Arbeit" }
quests[52055] = { id = 52055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erz um Auge", description = "Ich hab noch 'ne letzte Bitte, bevor ich geh'n kann.\n\nIch möcht noch 'n letztes Mal den Sonnenuntergang seh'n. Ich kenn da 'ne Verzauberung und hab auch schon alle Materialien, die ich dazu brauch, außer dem Metall.\n\nBitte, bringt mir zwanzig Platinbrock'n.\n\nIch hab die Geister gebet'n, mir das Erz zu beschaff'n, aber sie hör'n nich' mehr auf mich. Genau darum hab ich die Karte ja an 'nem Ort versteckt, an dem sie nur jemand find'n würde, der mir helf'n kann.\n\nWenn Ihr mir helft, bring' ich Euch alles bei, was ich über die Platingewinnung weiß.", sourceObjective = "Sammelt 20 Platinbrocken.", progress = "Die Elemente ruf'n mich. Habt Ihr die Platinbrock'n?", completion = "Ausgezeichnet!\n\n<Ta'mil murmelt leise eine Beschwörungsformel, während er die Platinbrocken in seinen Händen wiegt. Ein grelles Licht bricht zwischen seinen Fingern hervor und erlischt wieder, als er verstummt. Er wendet sich Euch mit einem Lächeln zu und hält Euch etwas entgegen, das wie ein Paar Platinaugäpfel aussieht.>\n\nIch sehe Euch. Und ich dank' Euch. Ich schätze, der nächste Sonnenuntergang wird mein letzter sein.\n\nWas Eure Ausbildung angeht...\n\n<Ta'mil hebt einen massiven, mit Platinadern durchzogenen Stein auf und offenbart Euch die Geheimnisse der Gewinnung des Metalls.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52056] = { id = 52056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flut des Schicksals" }
quests[52057] = { id = 52057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen den Sturm" }
quests[52058] = { id = 52058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kurzlebiger Frieden", description = "{name},\n\ngerade als die Bedrohung unserer Welt durch die Legion schwindet, taucht schon eine neue auf. Ich muss Euch schweren Herzens einmal mehr bitten, Euer Leben für die Allianz zu riskieren.\n\nIch habe beunruhigende Nachrichten von unseren in Orgrimmar stationierten Agenten erhalten.\n\nIch erwarte Euch auf Burg Sturmwind zur weiteren Besprechung.", sourceObjective = "Meldet Euch bei König Anduin Wrynn auf Burg Sturmwind.", completion = "Ihr habt im Namen der Allianz immer wieder aufs Neue tapfer gekämpft. Dafür stehe ich tief in Eurer Schuld.\n\nAber ich fürchte, dass ich Euch noch mehr abverlangen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[52059] = { id = 52059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da versinkt sie" }
quests[52060] = { id = 52060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstand der Horde", description = "Bedenkt man, wie sehr Azerit die Art der Kriegsführung verändern kann, ist es kaum verwunderlich, dass der Kriegshäuptling die Hände danach ausstreckt. Berichten zufolge hat sie eine Armee in Richtung der großen Wunde in Silithus in Marsch gesetzt.\n\nWährend des Feldzugs auf Argus kämpften die Helden von Horde und Allianz Seite an Seite. Dass Sylvanas bereit ist, diesen Bund einfach so aufzukündigen...\n\nSprecht mit Mathias Shaw. Ich möchte, dass Ihr unsere Präsenz in Silithus überwacht.", sourceObjective = "Meldet Euch bei Meister Mathias Shaw, um weitere Anweisungen zu erhalten.", completion = "Wartet! Unsere Berichte waren falsch!", sourceObjectiveStatus = "unverified-source-field" }
quests[52061] = { id = 52061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eikceps das Schwein!", sourceObjective = "Eikceps schaut Euch mit weit aufgerissenen Augen an, nachdem er mit angesehen hat, wie sein früheres Herrchen getötet wurde. Er scheint nun bereit, Euch zu folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52062] = { id = 52062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störung im Eschental", description = "Diese verdammte Horde! Schlaue Mistkerle, das muss ich ihnen lassen. Sie sind an der nördlichen Gabelung der Brachlande abgebogen und marschieren jetzt auf das Eschental zu.\n\nDie Truppen der Kaldorei haben bereits Segel gesetzt nach Silithus und müssten schon den halben Weg hinter sich haben. Die einzige Verteidigung in der Gegend ist die darnassische Stadtwache. Sie ist auf dem Weg nach Astranaar, aber gegen eine Armee wird sie nicht lange standhalten. Ihr kommandierender Offizier heißt Delaryn Sommermond.\n\nFindet sie, {name}, und verschafft uns etwas Zeit. Wir werden unsere Flotte so schnell wie möglich dort hinschicken.", sourceObjective = "Erstattet Hauptmann Delaryn Sommermond in Astranaar Bericht.", completion = "Hat Euch Malfurion gesandt?", sourceObjectiveStatus = "unverified-source-field" }
quests[52063] = { id = 52063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberpatrouille" }
quests[52064] = { id = 52064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Felder" }
quests[52065] = { id = 52065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlimmer als es aussieht", description = "So schlimm die Lage hier auch sein mag, wir haben noch die Oberhand.\n\nAn der Lichtkuppe sieht es weitaus übler aus. Sie sind dem Hauptangriff näher und brauchen alle Hilfe, die sie bekommen können.\n\nMacht Euch auf den Weg dorthin und schaut, ob Ihr helfen könnt.", sourceObjective = "Sprecht mit Felecia Götzstein an der Lichtkuppe.", completion = "Patrick ist ein guter Mann. Wenn er Euch vertraut, ist Eure Hilfe willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52067] = { id = 52067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlebende", description = "Patrick und Derek Eckhart haben eine Hütte nördlich der Stadt. Wie ich die beiden kenne, nehmen sie Überlebende aus Brennadam gern auf.\n\nSchaut bei Patrick vorbei und seht, ob die beiden Hilfe brauchen.", sourceObjective = "Sprecht mit Patrick Eckhart an der Hütte der Eckharts.", completion = "Calvin schickt Euch? Wir können alle Hilfe brauchen, die Ihr uns geben könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[52068] = { id = 52068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder helfen, aber anderswo", description = "Ihr wart uns eine große Hilfe. Und jetzt haben wir jede Menge Gold, das es aufzuteilen gilt! \n\nIhr solltet nach Westen nach Seebrise gehen. Seht es als Urlaub und macht Euch keine Sorgen um das Gold. Wir kommen hier schon klar. Wenn Ihr zurückkommt, haben wir Euren Anteil bereit.\n\nIhr würdet hier nur im Weg stehen.", sourceObjective = "Sprecht mit Leutnant Bauer in Seebrise.", completion = "Schuldet er Euch etwa Geld? Er scheint immer Leute zu schicken, denen er Geld schuldet!", sourceObjectiveStatus = "unverified-source-field" }
quests[52069] = { id = 52069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Kanonenfutter", description = "Leo Schilders in der Totenschwemme ist ein Gauner, aber er weiß, was für eine Bedrohung die Naga darstellen. Er wird uns Männer zu Hilfe schicken, wenn wir darum bitten, auch wenn die meisten eher Kanonenfutter sind.\n\nReist zur Totenschwemme und bittet um Hilfe.", sourceObjective = "Sprecht mit Leo Schilders in der Totenschwemme.", completion = "So übel wie die Eisenfluträuber uns mitspielen, sollte es genügend freiwillige Helfer für uns geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[52070] = { id = 52070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauer auf der Lauer", description = "Seit der Angriff der Horde begonnen hat, haben wir nichts mehr von der Küste gehört. Meldet Euch bei Leutnant Bauer in Seebrise und schaut nach, ob sie in Sicherheit sind.", sourceObjective = "Sprecht mit Leutnant Bauer in Seebrise.", completion = "Schön zu hören, dass Frederike wohlauf ist. Aber hier könnten wir Euch auch gut brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52071] = { id = 52071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter dem Borstenrücken" }
quests[52072] = { id = 52072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht von Elune", description = "Meine Schwestern liegen getötet auf der weichen Erde des Eschentals.\n\nMan lehrt uns, mit Verlusten zu rechnen. Soldaten sterben in Schlachten. Aber das... war ein verabscheuungswürdiger Angriff, selbst für die Horde.\n\nWir mögen wenig Zeit zum Trauern haben, aber anders als unsere Feinde sind wir keine Wilden.\n\n{name}, würdet Ihr bitte mit mir Gebete an Elune sprechen, um die Gefallenen zu ehren? Ihre Irrwische verdienen das Licht ihres Segens.", sourceObjective = "Ehrt die gefallenen Soldaten in Astranaar.", completion = "Elune segne Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[52073] = { id = 52073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bittgesuch an Krag'wa", description = "Nichts! Ich kann einfach nich' glauben, dass die Waffe keine Wirkung hatte!\n\nVerflucht sollen Ateena und ihre dunkle Magie sein! Wir müss'n irgendwie da raufkomm', sie ein für alle ma' töt'n und die Barriere entfernen!\n\nAber wie soll'n wir nur dort hochkommen... ach, natürlich! Krag'wa! \n\nDer Loa der Frösche hasst die Bluttrolle. Ich bin sicher, er wird uns helf'n. Dann können wir Ateenas Wahnsinn endlich ein Ende setz'n.", sourceObjective = "Beschwört Krag'wa und bittet ihn um Hilfe.", completion = "Das war's. Die Jagd is' vorbei!\n\nJetzt werd'n wir dieser Bedrohung für meine Heimat ein für alle Mal ein Ende setz'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[52074] = { id = 52074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung", description = "<Festländer/Festländerin>! Einen Augenblick! Ich könnte hier wirklich Hilfe brauchen!\n\nIch war mit meinem Trupp auf der Jagd in den Ruinen von Gol Koval, als die Steine begannen, uns anzugreifen! So etwas habe ich noch nie erlebt. Waldläuferin Wons hat Herzog und mich ausgeschickt, um medizinische Vorräte für unsere Verletzten zu beschaffen.\n\nHerzog wurde zwar nicht von diesen besessenen Steinmonstern getroffen, aber mit den Spinnen in der Gegend hatte er nicht so viel Glück. Er kommt schon wieder auf die Beine, wenn er hier noch ein bisschen rastet, aber meine Mannschaft braucht diese Vorräte!\n\nBitte bringt sie zu Waldläuferin Wons!", sourceObjective = "Bringt die Vorräte zum Waldläuferlager in Gol Koval.\n\nBereitgestellter Gegenstand:", completion = "Rebecca hat Euch geschickt? Gutes Mädchen! Ihr kommt gerade rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[52075] = { id = 52075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verknöchert", description = "Als ob diese lebenden Felsen nicht schon schlimm genug wären, scheinen die Untoten sich auch noch aus dem Boden zu hieven!\n\nDies war früher eine Siedlung der Drust, also sind das wahrscheinlich Drustknochen. Sie hassten uns und im Moment beruht das auf jeden Fall auf Gegenseitigkeit.\n\nIch weiß nicht, was sie so aufgescheucht hat, aber sie sind eine Gefahr für uns und alle anderen. Werdet sie los und ich belohne Euch für Eure Arbeit.", sourceObjective = "Besiegt 8 rachsüchtige Knochen.", completion = "Hoffentlich bleiben diese Monster jetzt liegen. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[52113] = { id = 52113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol'jin, Sohn von Sen'jin", description = "Sogar auf den Echoinseln ham wir von der Tradition des Goldwegs gehört.\n\nWir müssen mit dem König lauf'n un' die Leistungen von Vol'jin würdigen, dann is' sein Geist bei den uralt'n Königen willkomm'.\n\nIch trag' die Asche un' Ihr zündet die Feuer an.\n\nIhr müsst wiss'n, dass jedes Stammesmitglied gegen uns antreten kann. Ihr als unser Champion müsst sie dann abwehr'n.", sourceObjective = "Begleitet Vol'jins Asche nach Atal'Dazar.", completion = "Vol'jin. Ich muss zugeb'n, dass seine Taten mich beeindruck'n. Hätten wir uns in dieser Welt getroff'n, hätten er und ich sicher 'ne Menge gemeinsam gehabt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52114] = { id = 52114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen wahren Anführer ehren", description = "Vol'jin. Ich hab oft gemerkt, wie mir der Geist von unsrem alten Häuptling was zugeflüstert hat. Seine Stärke war das Lebensblut vom Dunkelspeerstamm. Einige sag'n auch, er war der Geist der wahren Horde.\n\nPrinzessin Talanjis Angebot is' großartig. Ich werd mit Vol'jins Asche nach Atal'Dazar reis'n.\n\nWenn Ihr uns bei dieser Prozession begleit'n wollt, treff'n wir uns am berühmten Goldweg.", sourceObjective = "Trefft Euch mit Meister Gadrin am Goldweg in Zuldazar.", completion = "Die Macht hier... is' in der Erde selbst zu find'n. Die Geister sin' stark un' uralt in diesem Land.", sourceObjectiveStatus = "unverified-source-field" }
quests[52115] = { id = 52115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schatten des Kraken" }
quests[52116] = { id = 52116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein sanftes Leuchten", description = "Die Irrwische... Sie singen voller Sorge, aber auch mit Bestimmtheit. Der Wald regt sich und erstrahlt in ihrem Licht.\n\nDieser Klang... in der Ferne. Ist es unser Shan'do?\n\nSchnell, {name}! Malfurion ruft!", sourceObjective = "Findet Malfurion im Eschental.", completion = "Ich bin froh, dass Ihr gekommen seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[52117] = { id = 52117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter dem Borstenrücken" }
quests[52118] = { id = 52118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Konkurrenz absägen", description = "Eigentlich hatte ich nie viel fürs Kämpfen übrig, aber ich will verdammt sein, wenn diese Unholde glauben, sie bekommen dieses Sägewerk.\n\nEs wird wohl das Beste sein, wenn wir das Gebiet schnell säubern. Schnappt Euch eine Axt und zeigt mir, was in Euch steckt.", sourceObjective = "Nehmt Euch eine robuste Axt und sammelt 5 Scheite frisch gespaltenes Holz von dem Setzling in der Nähe.", progress = "Worauf wartet Ihr?", completion = "Ihr seid ein Naturtalent.", sourceObjectiveStatus = "unverified-source-field" }
quests[52119] = { id = 52119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinazeritextraktion", sourceObjective = "Verwendet die Ziegenschere bei 1 sanftmütigen Ziegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52120] = { id = 52120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomenazeritextraktion", sourceObjective = "Verwendet die Ziegenschere bei 1 sanftmütigen Ziegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52122] = { id = 52122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlassen sein", description = "Machen wir uns auf den Weg. Zelling ist jetzt wahrscheinlich bei seiner Familie.\n\nEntweder sind sie glücklich wiedervereint und er hilft uns, Valentin zu finden... oder er hilft uns einfach, Valentin zu finden.\n\nAuf geht's.", sourceObjective = "Begleitet Lilian Voss und findet Thomas Zelling.", completion = "Ausgezeichnete Arbeit. Ich habe mich schon gefragt, warum Kyra weggerufen wurde. Zum Glück für Lilian war es eine gute Sache.\n\nUnser neuer Verbündeter gewöhnt sich an sein neues Leben. Bald werden wir bereit sein, Marschall Valentin zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[52124] = { id = 52124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des anderen Leid" }
quests[52126] = { id = 52126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich glaub, mein Schwein beißt", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52127] = { id = 52127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wolfsbau", description = "Der Überfall, den Ihr auf den Wolfsbau im Tiragardesund geplant habt, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zum Wolfsbau im Tiragardesund und baut dort Befestigungsanlagen.\n\nDer Wolfsbau wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Allianz spielen.\n\nGeht mit Ehre!", sourceObjective = "Beansprucht den Wolfsbau für die Horde.", completion = "Throm-Ka, {name}. Hier ist ein ausgezeichneter Platz für einen Außenposten! Dank Eurer Führung hat die Horde einen weiteren Stützpunkt im Tiragardesund!", sourceObjectiveStatus = "unverified-source-field" }
quests[52128] = { id = 52128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fährenpass", description = "<Carsten nimmt ein wichtig aussehendes Dokument aus seiner Jackentasche, unterzeichnet es und hält es Euch entgegen.>\n\nHier, damit habt Ihr Zugang zum Fährsystem.", sourceObjective = "Sprecht mit Carsten Jammerthal und erhaltet den Fährenpass.", completion = "Überall entlang der inneren Küstenlinie des Sunds befinden sich Fährhäfen. Vergesst das nicht während Eurer Reisen!", sourceObjectiveStatus = "unverified-source-field" }
quests[52129] = { id = 52129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energieprobleme", description = "Rozzy gehört zum Ausgrabungstrupp. Sie ist mit Werkzeug losgezogen, um einen Plan auszuarbeiten, wie man diese Rekonfigulatoren aufgeladen halten kann.\n\nGeht und seht nach, ob sie Hilfe braucht!", sourceObjective = "Meldet Euch bei Rozzy.", completion = "Wenn Merd möchte, dass Ihr helft, dann habe ich genau das Richtige!", sourceObjectiveStatus = "unverified-source-field" }
quests[52130] = { id = 52130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seemannsgarn: Carpe Diem", description = "Pah, hört nicht auf diese Landratten. Die haben in ihrem Leben noch keinen Tag mit ehrlicher Arbeit verbracht!\n\nBevor sie mich getroffen haben, waren sie so trocken wie der Sand an der Küste bei Ebbe.\n\nIch erzähle Euch die Geschichte von dem Tag, an dem wir uns getroffen haben. Das war auch der Tag, an dem ich die Werft vor dem größten, fiesesten, gewaltigsten Monster der salzigen Tiefen gerettet habe, das Ihr Euch vorstellen könnt!", sourceObjective = "Hört Euch die Geschichte von Steuerfrau Haken an.", completion = "Was für eine Geschichte, was, Junge?! Und erzählt sie auf jeden Fall auch Euren Freunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[52131] = { id = 52131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen einander", description = "Mein Vater glaubt, er wär nachsichtig mit mir. Er regiert seit zweihundert Jahren, viele Lebensspannen für 'nen Troll. Aus seiner Sicht sind die Bedrohungen für unser Königreich geringfügig.\n\nIch hab zu viel geseh'n, um das zu glauben.\n\nDa mein Vater und seine Ratgeber nich' helfen wollten, hab ich mich an jemand'n gewandt, der es tun wird.\n\nEuer Kriegshäuptling braucht unsere Flotte und ich brauch ihre Champions. Folgendes müss'n wir also tun.", sourceObjective = "Hört Prinzessin Talanji zu.", completion = "Entscheidet Euch, wenn Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[52132] = { id = 52132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis für Piraterie", description = "Piraten lieben Rum noch mehr als Gold. Also suchen wir ihre Rumvorräte und jagen sie in die Luft. Wenn der ganze Rum weg ist, werden viele der Piraten weiterziehen.\n\nBenutzt meine speziellen Fasssprengbomben, um die versteckten Rumvorräte der Piraten zu vernichten.", sourceObjective = "Zerstört 6 Rumvorräte der Piraten.", completion = "Das war hart, aber notwendig.", sourceObjectiveStatus = "unverified-source-field" }
quests[52133] = { id = 52133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guter Junge!" }
quests[52139] = { id = 52139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtige Angelegenheiten", description = "Prinzessin Talanji sollte bereit sein, mit Euch drüber zu sprech'n, wie man unser Reich rett'n kann.\n\nIch an Eurer Stelle würd jetzt zu ihr geh'n und mit ihr red'n. Sie hat in der Nähe 'ne Planungszone eingerichtet.", sourceObjective = "Sprecht mit Prinzessin Talanji im Großen Siegel.", completion = "Gut, Ihr seid wieder da. Es gilt, keine Zeit zu verlier'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[52140] = { id = 52140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dorniges Problem" }
quests[52142] = { id = 52142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte auffüllen" }
quests[52143] = { id = 52143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleinere Knechte", sourceObjective = "Befreit 6 schuftende Straßenkinder aus der Aschenwindgießerei.", sourceObjectiveStatus = "unverified-source-field" }
quests[52144] = { id = 52144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kernschmelze in der Gießerei", sourceObjective = "Tötet 10 Betriebswachposten, Betriebsvollstrecker oder Betriebsfüsiliere.", sourceObjectiveStatus = "unverified-source-field" }
quests[52145] = { id = 52145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hau-Ruck!" }
quests[52146] = { id = 52146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutgetränkter Sand", description = "Und damit ist unsere Mission abgeschlossen.\n\nStellen wir sicher, dass Guzbert und Kelsey sicher von ihren Ausgrabungsstätten zurückkommen, dann können wir uns wieder an freundlichere Gestade begeben.", sourceObjective = "Wartet, bis Guzbert Gizmoflanke und Kelsey Stahlfunken zurückgekehrt sind.", progress = "Sollte nicht mehr lange dauern!", completion = "Guzbert ist... was? Nein!", sourceObjectiveStatus = "unverified-source-field" }
quests[52147] = { id = 52147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hordenlähmung", description = "Unsere Späher berichten, dass einer der Hauptmänner von Sylvanas' Dunklen Waldläufern sich in Nazmir aufhält.\n\nDie Dunklen Waldläufer gehören zu Sylvanas' tödlichsten Kämpfern und Spähern. Einen ihrer Anführer zu töten, wird die Operationen der Horde lahmlegen.\n\nShandris Mondfeder wird diese Operation in Nazmir leiten. Ihr müsst Euch sofort dort hinbegeben und zuschlagen, bevor uns diese Chance entgeht.", sourceObjective = "Sprecht mit Großadmiralin Jes-Tereth, um nach Nazmir zu reisen.", completion = "Nazmir. Wir sollten zusehen, dass wir diesen Ort hinter uns lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52148] = { id = 52148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freihafen: Ende eines Piraten", description = "Hey, öhm, bei persönlichen Angelegenheiten bitte ich normalerweise nicht um Hilfe, aber ich weiß auch, wann ich keine Chance habe.\n\nJemand muss Harlan aus dem Verkehr ziehen.\n\nEr ist verrückt. Ich war damals Zeuge seiner ganzen Untaten... Deswegen habe ich Freihafen auch verlassen.\n\nUnd denkt nicht, dass Ihr mir damit einen Gefallen tut, obwohl es natürlich ein RIESIGER Gefallen wäre. Nein, Ihr macht damit die Meere zu einem sichereren Ort für alle. Es wäre praktisch eine gemeinnützige Heldentat.\n\n<Finn beugt sich zu Euch und flüstert.>\n\nEs ist übrigens ein enormes Kopfgeld auf ihn ausgesetzt!", sourceObjective = "Tötet Harlan den Schmierigen in Freihafen (Dungeon).", completion = "Ich muss zugeben, als ich Euch zum ersten Mal in der Gefängniszelle sah, hatte ich keine Ahnung, was all der Aufwand sollte.\n\nAber Ihr habt Euch wirklich für mich eingesetzt. Ihr habt Euch für alle hier eingesetzt.\n\nDanke, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[52149] = { id = 52149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Flamme", description = "Mein Volk hat genug Verluste und Qualen erlitten, als es sich in der Finsternis abmühte, die Drustvar einhüllte. Aber jetzt haben wir wieder etwas Licht zurückerhalten. Wir haben die Mittel und den Willen, um unser Land dem anhaltenden Bösen wieder zu entreißen. Eure Hilfe hat vieles davon ermöglicht.\n\nIch werde meine Eltern vermissen. Obwohl ihr Ende düster war, waren sie doch Familie. Doch meine Pflicht als Oberhaupt von Haus Kronsteig ist klar. Die Toten kommen alleine zurecht. Ich muss mich um die Lebenden kümmern und sie anführen.\n\nIch muss eine kurze Zeremonie abhalten. Würdet Ihr mir assistieren?", sourceObjective = "Assistiert bei der Zeremonie an der Statue in Aroms Wehr.", progress = "Danke.", completion = "Ich muss weiterhin mein Haus in Ordnung bringen, aber unsere Beziehungen mit dem Rest von Kul Tiras wurden viel zu lange vernachlässigt. Ich muss mich hier erst noch um einige andere Dinge kümmern, aber ich werde bald nach Boralus gehen, um den Rest auf den rechten Weg zu bringen.\n\nMeinen tief empfundenen Dank für alles, was Ihr getan habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[52150] = { id = 52150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man einen Dunklen Waldläufer tötet", description = "Lasst uns den Plan besprechen. Wir werden nicht viele Chancen erhalten, einen Hauptmann der Dunklen Waldläufer von Sylvanas zu töten.", sourceObjective = "Hört Euch Shandris Mondfeders Plan an.", completion = "Unser Plan steht. Machen wir uns auf den Weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[52151] = { id = 52151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine vereinte Nation", sourceObjective = "Nehmt an der Ratsversammlung auf dem Platz der Einheit teil.", completion = "Ihr habt meine Familie und mein Land wieder vereint, Held.\n\nMein Herz fühlt sich nach all den Jahren zum ersten Mal wieder ganz an.\n\nIch kann Euch nicht genug danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[52153] = { id = 52153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerung von Boralus: Lady Aschenwinds Rückkehr", description = "Wenn Aschenwind denkt, dass wir einfach stillhalten, während sie ihren Coup durchzieht, hat sie sich schwer getäuscht. Die Einwohner von Boralus werden sie bis zum letzten Mann bekämpfen.\n\nIch möchte, dass Ihr ihnen an der Front helft, {class}. Geht mit Taelia zu den Docks und greift die Feinde an. \n\nMit etwas Glück kommen wir hier vielleicht lebend raus.", sourceObjective = "Schließt die Belagerung von Boralus (Dungeon) ab.", completion = "Das war unglaublich! Ich hatte ja keine Ahnung, dass Lady Jaina so mächtig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[52154] = { id = 52154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser nächstes Ziel", sourceObjective = "Hört den Anführern der Allianz bei der Besprechung des Plans zu.", completion = "Ich bin dankbar für Allerias Klugheit und die Bereitschaft unserer neuen Verbündeten, die Führung zu übernehmen. Diese neue zweigleisige Strategie eröffnet uns zusätzliche taktische Möglichkeiten, die wir ausschöpfen können.\n\nIch muss Alleria bitten, mit mir zurückzubleiben, um unsere Bemühungen an beiden Fronten zu koordinieren. Ihr müsst Euch Umbric anschließen, um den Erfolg dieser Mission zu gewährleisten. Viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[52155] = { id = 52155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schätze der Gezeiten", sourceObjective = "Plündert 8 gestrandete Versorgungsgüter im Klagenden Priel.", sourceObjectiveStatus = "unverified-source-field" }
quests[52156] = { id = 52156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollaner in Bedrängnis", description = "Unsere erste Aufgabe ist die Rettung der Tortollaner, die von den Bluttrollen gefangen genommen wurden.\n\nKeeshans Bericht zufolge kennen sich die Tortollaner mit allen Dingen in Nazmir aus. Sie sollten über alle Schritte der Horde hier Bescheid wissen.\n\nDie Tortollaner bleiben in den meisten Fällen neutral. Wenn wir ihnen einen fairen Handel anbieten, werden sie uns Details über die Pläne der Horde verraten.\n\nWir treffen uns danach an unserem anderen Außenposten Rotfelds Wacht, nördlich von Torgas Ruh.", sourceObjective = "Rettet 6 gefangene Tortollaner vor den Bluttrollen.", progress = "Was müsst Ihr sonst noch wissen?", completion = "Wir haben die benötigten Informationen von den Tortollanern erhalten. Wir müssen uns beeilen. Die Zeit drängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52157] = { id = 52157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schaurige Begegnung" }
quests[52158] = { id = 52158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wilde Jagd", description = "Die Bluttrolle in Nazmir sind schlicht und ergreifend Monster. Keine Kultur, keine Empathie. Diese Kreaturen kennen nur pure Zerstörung.\n\nTöten wir sie und dann soll ihr dunkler Gott, oder was immer sie anbeten, sich mit ihnen herumschlagen.", sourceObjective = "Tötet 15 Bluttrolle und ihre Verbündeten in Torgas Ruh.", completion = "Wir haben schon viel zu lange Angriffe der Bluttrolle auf die Siegesfeste abwehren müssen. Gut zu wissen, dass sie bekommen haben, was sie verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52159] = { id = 52159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrubbt das!" }
quests[52160] = { id = 52160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte auffüllen" }
quests[52163] = { id = 52163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geflügelte Taifun" }
