quests[52165] = { id = 52165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Automatisiertes Chaos", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
