quests[52167] = { id = 52167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuberungsaktion" }
quests[52168] = { id = 52168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiße Nummer" }
quests[52169] = { id = 52169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Matriarchin" }
quests[52170] = { id = 52170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Areiels Ende", description = "Die Tortollaner haben uns Hauptmann Areiels Standort sowie neue Informationen mitgeteilt. Sie trägt ein Sendschreiben der Horde bei sich.\n\nWenn die Horde Areiel ein Sendschreiben schickt, muss es extrem wichtig sein. Wir müssen es bekommen und dafür sorgen, dass Halford die Informationen erhält.\n\nIch habe früher einmal mit Areiel Seite an Seite gekämpft. Sie ist unglaublich mächtig. Keeshan und ich werden Euch helfen, sie auszuschalten.\n\nViel Glück, {name}.", sourceObjective = "Beschafft das Sendschreiben der Horde von Hauptmann Areiel.", progress = "Habt Ihr das Sendschreiben erhalten?", completion = "Ich weiß, dass ich mich über Areiels Tod nicht freuen sollte... aber ein Teil von mir ist froh, dass ihre Schreckensherrschaft beendet ist.\n\nWas ist mit dem Sendschreiben?", sourceObjectiveStatus = "unverified-source-field" }
quests[52171] = { id = 52171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Option: Feuer", description = "Ich dachte ja schon, es könnte nicht schlimmer kommen, aber jetzt hat sich die Horde rund um den Sitz von irgendeinem Todesgott niedergelassen.\n\nDank meiner Zeit in den ersten drei Kriegen kann ich mir denken, was sie mitgebracht haben. Medikamente, Rüstung, Verpflegung...\n\nUnd bestimmt auch Opfergaben für diesen Bwonsamdi-Typen. Zerstört alle Vorräte der Horde, um sie wissen zu lassen, dass wir sie hier nicht dulden werden.", sourceObjective = "Verbrennt Opfergaben für Bwonsamdi, Arsenalvorräte, Nahrungsvorräte und medizinische Vorräte in der Nekropole.", completion = "Ohne ihre Vorräte wird die Horde gezwungen sein, sich aus der Nekropole zurückzuziehen. Ein schöner Sieg für uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[52172] = { id = 52172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie dürfen hier nicht bleiben", description = "Kaum zu glauben, dass die Horde in der Nekropole bereits Fuß gefasst hat. Wir müssen sie aufhalten.\n\nDiesmal ist es einfach. Tötet an diesem verfluchten Ort so viele Mitglieder der Horde, wie Ihr könnt, aber haltet nach einem Typen namens Bwonsamdi Ausschau.\n\nEr scheint so eine Art Todesgott zu sein. Mit ihm können wir es keinesfalls aufnehmen, aber warum nicht ein paar seiner Anhänger zu ihm schicken?\n\nBesser, sie verrotten in der Nekropole, als dass sie die Lebenden plagen.", sourceObjective = "Tötet 12 Soldaten der Horde in der Nekropole.", completion = "Gut, je weniger wir uns an diesem verfluchten Ort um die Horde kümmern müssen, desto besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[52173] = { id = 52173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Leerenelfen sind in Bereitschaft", sourceObjective = "Sprecht mit Großadmiralin Jes-Tereth und reist nach Xibala.", completion = "Meine Späher haben die Umgebung bereits erkundet und einen umfassenden Bericht für uns angefertigt. Wir beide können sofort mit unserer Phase der Mission beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52174] = { id = 52174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangen in den Untiefen" }
quests[52179] = { id = 52179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkter Widerstand" }
quests[52180] = { id = 52180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verbrennadammte Schande" }
quests[52181] = { id = 52181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauch und Schatten" }
quests[52182] = { id = 52182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerit muss mit" }
quests[52183] = { id = 52183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Plan, der funktioniert", description = "Derek Prachtmeers Leichnam in Besitz zu haben, ist ein noch größerer Segen, als wir geplant hatten.\n\nValentin ist auferstanden, aber ich glaube, es wäre besser, Derek noch eine Weile tot ruhen zu lassen.\n\nEs wird Zeit, unsere neuen Verbündeten gewinnbringend einzusetzen.", sourceObjective = "Hört Euch Nathanos' Plan an und begebt Euch dann nach Raubhafen.", completion = "Und jetzt warten wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[52184] = { id = 52184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualrelikte", description = "Der Grund, warum ich Euch auf dieser Mission begleite, ist nicht nur die Vertrautheit. Das Abyssische Szepter ist mit einem Ritual versiegelt und die dafür benötigten Komponenten sind im Besitz von drei Leutnants in dieser Anlage.\n\nIhr holt die Relikte, ich werde das Ritual abhalten und dann greifen wir uns das Szepter und verschwinden wieder.", sourceObjective = "Beschafft den Kompass der Klarheit, die Kuriosität der Tiefen und den Schlüssel des Meeres in der Sturmsangabtei.", progress = "Habt Ihr die Relikte schon eingesammelt?", completion = "Bitte erzählt mir nicht, was Ihr alles niedermetzeln musstet, um an die Relikte zu kommen. Ich will es lieber nicht wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52185] = { id = 52185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gut platziertes Portal", description = "Wir haben die Front hier unter Kontrolle. Ich schicke Euch und Zelling nach Boralus, damit Ihr das Abyssische Szepter beschafft.\n\nOculeth konnte einen sicheren Standort für ein Portal ausmachen. Geht jetzt.", sourceObjective = "Benutzt das Portal nach Boralus, um Euch mit Thomas Zelling in der Sturmsangabtei zu treffen.", completion = "Ich habe hier einst studiert, und nun...\n\n<Zelling räuspert sich.>\n\nWir haben eine Aufgabe zu bewältigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52186] = { id = 52186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Großteil der Wache", description = "Wenn alles nach Plan läuft, hat Prachtmeer ihre Elitetruppen ausgesandt, um den Leichnam ihres Sohnes zu bergen.\n\nStellen wir sicher, dass sie uns nicht bei unserer eigentlichen Mission stören, hm?", sourceObjective = "Tötet 12 Prachtmeerwachen auf der Sirenentochter und der Tapferen Rose.\n\nHobart Wurfhammer kann Euch zu den Schiffen hinausfliegen.", completion = "Es ist fast so, als könnte ich von hier aus ihre Schreie hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[52187] = { id = 52187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Kollegen", description = "Die Befehlshaber auf diesen Schiffen sind alte Kollegen von mir, {name}.\n\nSie haben sich ihren Rang nicht so wie ich durch harte Arbeit verdient, sondern durch Täuschung und Erpressung.\n\nIch finde, es ist nur recht und billig, wenn sie den Karmahammer zu spüren bekommen... oder welche Waffe auch immer Ihr bevorzugt.", sourceObjective = "Tötet Kapitän Gastrod und Wachkommandant Trunksal auf der Sirenentochter und Steuerfrau Miria auf der Tapferen Rose.\n\nHobart Wurfhammer kann Euch zu den Schiffen hinausfliegen.", completion = "Jede einzelne dieser Personen hatte genau das verdient, was sie von Euch bekommen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[52188] = { id = 52188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehren der Gezeitenweisen", description = "Das sind keine Gezeitenweisen mehr. Sie sind es nicht würdig, sich unserer Titel, unseres Prestiges oder unseres Wissens zu bedienen.\n\nSo viele der Lehrschriften liegen im ganzen Kloster verstreut, verloren für jene von uns, die übrig geblieben sind.\n\nWir müssen uns diese Schriften wiederholen. Sie sind in meinen Händen besser aufgehoben als in ihren.", sourceObjective = "Sammelt 5 Folianten der Gezeitenforschung in der Sturmsangabtei ein.", progress = "Ich werde nicht zulassen, dass die Forschung meiner Leute zu bösen Zwecken missbraucht wird.", completion = "Es ist gut zu wissen, dass die Forschung nicht in den Händen jener ist, die sie missbrauchen würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[52189] = { id = 52189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwirkte Seelen", description = "Die Gezeitenweisen hier haben sich der dunklen Magie verschworen und Mächten hingegeben, die sie nicht verstehen. Und meine Leute haben den Preis dafür bezahlt.\n\nEinst kannte ich sie, meine Brüder und Schwestern im Namen der Gezeiten. Doch nun sind sie verloren.\n\nVielleicht bin ich es auch.\n\nLäutert den Namen der Gezeitenweisen! Tötet diese Verräter!", sourceObjective = "Tötet 8 Archivare oder Beschwörer der Gezeitenweisen in der Sturmsangabtei.", completion = "Es war kein Vergnügen, Euch darum zu bitten, {name}. Aber es musste sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[52190] = { id = 52190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oberhand gewinnen", description = "Wir müssen das Abyssische Szepter sichern und von hier verschwinden, bevor die Kul Tiraner unsere Linien in Raubhafen durchbrechen.\n\nIch habe mich schlau gemacht, während Ihr weg wart. Ich glaube, ich habe herausgefunden, wo das Ritual durchgeführt werden muss.\n\nWenn Ihr bereit seid, können wir uns auf den Weg dorthin machen.", sourceObjective = "Helft Zelling, das Abyssische Szepter in der Sturmsangabtei zu sichern.", progress = "Nathanos und ich glauben, dass uns das abyssische Szepter dabei helfen kann, die Oberhand über die Flotte von Kul Tiras zu gewinnen. Wenn Ihr den Krieg gewinnen gewollt, dann braucht Ihr dieses Szepter.", completion = "Wir haben das Szepter... mit allen Vor- und Nachteilen, die es mit sich bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52191] = { id = 52191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangenes Leben", description = "Wie Lilian schon sagte, haben wir einen letzten Besucher.\n\nSollen wir ihn aufsuchen?", sourceObjective = "Helft Nathanos Pestrufer mit den verbleibenden Einheiten von Prachtmeer.", progress = "Hier gibt es nichts mehr für uns. Kehren wir zurück.", completion = "Wir haben das Szepter und den Leichnam von Derek...\n\nLasst uns irgendwo hingehen, wo es etwas... gastlicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[52192] = { id = 52192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezeitenhilfe", description = "Mit dem Leichnam von Derek und dem Abyssischen Szepter haben wir alles, was wir wollten. Lasst uns jetzt vor ihren Augen von hier verschwinden.\n\nWenn Ihr bereit seid, kehren wir nach Zuldazar zurück. Sylvanas soll von unseren Siegen erfahren.", sourceObjective = "Sprecht mit Nathanos Pestrufer und kehrt nach Zuldazar zurück.", completion = "Ein paar Kul Tiranische Schiffe auf dem Meeresgrund runden unsere Mission zufriedenstellend ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[52194] = { id = 52194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Ihr vielleicht bereut", description = "{name}, Genn Graumähne hat diesen Brief für Euch dagelassen. Er hat angedeutet, dass es sehr dringend ist. Ich wollte gerade nach Euch schicken.\n\n<Ihr öffnet den Brief und lest den Inhalt.>\n\"{name},\n\nIhr habt dem Volk von Kul Tiras geholfen, zusammenzufinden und sich der Allianz anzuschließen. Vielleicht könnt Ihr jetzt auch einer Mutter und ihrer Tochter helfen, zusammenzufinden.\n\nTrefft mich am Familiendenkmal bei Burg Prachtmeer. Mit Glück können wir Lordadmiralin Prachtmeer davon überzeugen, die Hinrichtung ihrer Tochter aufzuschieben.\n\n- Genn Graumähne\"", sourceObjective = "Sprecht mit Genn Graumähne bei der Gedenkstätte von Burg Prachtmeer.", completion = "<Katherine sieht einen Moment zur Seite.>\n\nPriscilla... Lady Aschenwind hat mich davon überzeugt, meine Tochter ins Exil zu schicken. Ich erkenne jetzt, dass sie aus puren Eigennutz gehandelt hat, und ich weiß nicht einmal, ob meine Tochter noch lebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52196] = { id = 52196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochen im Sand" }
quests[52197] = { id = 52197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein langer Weg", description = "Für jeden Feind, den wir töten, erscheinen zwei neue.\n\nWir sind zu wenige, um ihnen die Stirn zu bieten. Wir müssen uns zurückfallen lassen, {name}. Mit der richtigen Strategie können wir auch gegen eine Überzahl gewinnen.\n\nWir werden uns daher in Darnassus neu aufstellen. Ich werde Delaryn herbeirufen.", sourceObjective = "Trefft Euch mit Malfurion und Delaryn in Darnassus.", completion = "Es herrschen schlimme Zeiten, {name}. Wir müssen unsere Kräfte sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[52198] = { id = 52198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tank und Zank" }
quests[52199] = { id = 52199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rum-Gepolter!" }
quests[52200] = { id = 52200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildkrötentaktiken" }
quests[52203] = { id = 52203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Papierkrieg", description = "Der Geheimdienst des Oberkommandos ist sich sicher, dass Handelsprinz Gallywix im Moment in Zuldazar ist. Meine Späher konnten ihn im Bilgewasserlager aber nicht ausfindig machen. Er wird sich also wahrscheinlich irgendwo in der Umgebung aufhalten.\n\nGoblins arbeiten nicht umsonst. Es muss jemanden geben, der die übrigen Minenarbeiter herumkommandiert. Findet die verantwortliche Person, schaltet sie aus und durchsucht sie nach Hinweisen auf Gallywix Aufenthaltsort.", sourceObjective = "Holt Euch die Befehle von Gallywix.", progress = "Habt Ihr etwas Nützliches gefunden?", completion = "<Magister Umbric liest die Befehle, die Ihr ihm überreicht, und lächelt.>\n\nGallywix ist ganz in der Nähe!", sourceObjectiveStatus = "unverified-source-field" }
quests[52204] = { id = 52204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Leerenlösung", description = "Das Bilgewasserkartell nimmt den Schutz seiner Investitionen in den Bergbau äußerst ernst. Meine Fährtenleser berichten von einer Menge großer Mechanzüge, die nicht nur eingesetzt werden, um Gestein zu brechen, sondern auch, um Angreifer zu überwältigen.\n\nIch bin mir zwar sicher, dass Ihr selbst mit diesen Mechs fertigwerden würdet, aber Eure Zeit ist dafür zu kostbar.\n\nNehmt diesen Leerensplitter und benutzt ihn, um die großen Mechs in die Leere zu schicken, wo sie niemandem mehr etwas anhaben können.", sourceObjective = "Benutzt Magister Umbrics Leerensplitter, um 4 Bilgewasserschürfer zu vernichten.", completion = "Die Macht der Leere ist grenzenlos, {name}, wenn man sie zu bändigen weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[52205] = { id = 52205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bilgewasserbonanza macht Bumm", description = "Ich habe kaum je einen Goblin getroffen, der meinen Respekt verdient, aber eines muss man ihnen lassen: Hartnäckig sind sie.\n\nDas Bilgewasserkartell, die Bande des Handelsprinzen Gallywix, hat bereits einen ganzen Trupp Minenarbeiter als Ersatz entsendet, um Azerit am nahegelegenen Strand abzubauen.\n\nDie Allianz wird gewiss dankbar sein, wenn Ihr ihre Bergbauaktivitäten noch einmal lahmlegen würdet.\n\nWenn unsere Kampftaktiken auch etwas unkonventionell sein mögen, steht mein Regiment bereit, um Euch zu helfen. Wenn Ihr unsere Hilfe braucht, ruft in die Leere und wir werden antworten.", sourceObjective = "Tötet 12 Bilgewässer Goblins und öffnet Leerenrisse, um Leerenelfen als Verbündete an Eure Seite zu rufen.", completion = "Ich bezweifle nicht, dass diese Goblins wieder ersetzt werden, wie die letzten, mit denen Ihr es zu tun hattet.\n\nAber wir haben immerhin ihre Fortschritte gebremst und unseren Verbündeten ein bisschen mehr Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[52207] = { id = 52207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerit muss mit" }
quests[52208] = { id = 52208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begegnung des Bösen", description = "Wir haben Glück. In diesem Sendschreiben geht es um ein Treffen von Talanji, Rokhan, Areiel und Blutprinz Dreven in den Ruinen von Zo'bal.\n\nDas ist unsere Chance, mehr über Dreven und seinen nächsten Schritt herauszufinden. Er hat unsere Soldaten in Vol'dun getötet, und dafür wird er jetzt zahlen.\n\nTrefft mich außerhalb der Ruinen von Zo'bal. Wir werden uns in die Ruinen schleichen, ihre Pläne belauschen und dann entscheiden, was wir als Nächstes tun.", sourceObjective = "Trefft Euch mit Shandris Mondfeder außerhalb der Ruinen von Zo'bal.", progress = "Gehen wir.", completion = "Dreven wird in einem geschlossenen Tunnel sein? Besser könnte es nicht laufen. Auf geht's.", sourceObjectiveStatus = "unverified-source-field" }
quests[52209] = { id = 52209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildkrötentaktiken" }
quests[52210] = { id = 52210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SOS auf hoher See", description = "Der Flotte ganz draußen im Hafen scheinen die Leute abzuwandern.\n\nFlugblätter machten die Runde. Sie scheinen etwas oder jemanden zu suchen.\n\nDiese Schiffe haben eine große Fahrt hinter sich, und sie haben noch viel vor sich.\n\nIhr solltet mal ganz unauffällig bei Käpt'n Grez'ko vorbeischauen. Fragt ihn, ob er Hilfe brauchen kann.", sourceObjective = "Sprecht mit dem Käpt'n.", completion = "Genau nach Euch hab ich gesucht, Mann! Ich hab 'ne Menge Geschicht'n gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[52211] = { id = 52211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roter Sonnenaufgang" }
quests[52212] = { id = 52212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Stromgarde" }
quests[52213] = { id = 52213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uraltes Kürschnermesser", description = "Im vernarbten Fleisch der Bestie findet Ihr eingebettet unter der Haut eine schartige, goldene Klinge.\n\nAls Ihr sie vorsichtig herauszieht, könnt Ihr Euch des Eindrucks nicht erwehren, dass es sich um ein altes Kürschnermesser der Zandalari handelt.\n\nDas solltet Ihr Rana der Schlitzerin zeigen.", sourceObjective = "Bringt das uralte Kürschnermesser zu Rana der Schlitzerin.\n\nBereitgestellter Gegenstand:", completion = "Ha ha! Wenn ich's nich' besser wüsste, würd ich glatt sagen, das ist das Kürschnermesser von meinem alten Meister.\n\nVor 'n paar Jahr'n is' er ausgezog'n, um ein paar Pelze zu sammeln, und nie wieder zurückgekehrt. Ich dacht mir, der Idiot muss von 'nem Baumstamm erschlag'n word'n sein.\n\nWenn das da unter der Haut der Bestie steckte, hat er wohl gedacht, er hätt sie getötet... bis sie wieder aufgewacht is', um ihn allezumach'n.\n\nSchön, auch mal 'ne lustige Geschichte zu hör'n. Danke dafür! Soll Euer Schad'n nich' sein.\n\n<Sie kichert noch immer vor sich hin, als sie Euch mit dem Messer ihres Meisters einen Trick für das Abziehen des Leders einer getöteten Bestie demonstriert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52214] = { id = 52214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeremonielle Gewänder", description = "Xanjo hat mich gebet'n, Materialien für ihn zu sammeln, damit er 'ne zeremonielle Rüstung anfertig'n kann.\n\nEr hat nach mehreren Krokiliskenbälgen gefragt, aber alle Bälge, die ich hab, ham Narben oder andere Makel.\n\nBitte besorgt mir 'n paar neue, makellose Krokiliskenbälge.\n\nDie best'n kommen von den Urschnappkiefern in Nazmir. Ihre Haut is' dick genug, um im Kampf keine Narb'n davonzutrag'n.\n\nWenn Ihr das für mich tut, zeig ich Euch, wie man noch besser Schuppen von... schuppigen Kreaturen gewinnt.", sourceObjective = "Sammelt 3 makellose Krokiliskenhäute von Urschnappkiefern in Nazmir.", progress = "Habt Ihr die Häute?", completion = "Ausgezeichnet!\n\nDie sind nich' übel! Na ja, brauchbar... die meist'n zumindest.\n\nIch muss sie nur noch säubern, bevor ich sie weitergeb'n kann. Aber egal, schaut zu, dann zeig ich Euch, wie man beim Häut'n solcher Schuppenviecher das Beste rausholt.\n\n<Rana demonstriert Euch anhand der von Euch beschafften Bälge ein paar kleine Tricks für eine bessere Technik und ein besseres Ergebnis.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52215] = { id = 52215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dickeres Garn", description = "{name}! Ich hatt gehofft, dass Ihr hier auftauch'n würdet!\n\nXanjo is' fast fertig mit der Arbeit an seiner zeremoniellen Rüstung. Aber es gibt 'n Problem.\n\nEr sagt, das von ihm verwendete Garn is' zu dünn und das Gewicht des Leders lässt die Nähte reiß'n.\n\nEr hat mich gebet'n, was Robusteres zu besorgen. Ich glaub, das dicke Netz der Dschungelnetzkriecher wär da genau das Richtige.\n\nSie sind im nördlich'n Vol'dun heimisch. Bringt mir 'n paar Stränge von ihren dicken Netzen, dann werd ich Euch alles erzähl'n, was ich über Schuppentiere weiß.", sourceObjective = "Erbeutet 5 Stränge der dicken Netze von Dschungelnetzkriechern in Vol'dun.", progress = "Und, habt Ihr die Seide?", completion = "Jau, das sollte geh'n. Wenn das Garn erstma' durch diese Netzstränge ersetzt is', wird die Rüstung ewig halt'n!\n\nAllerdings... is' das Zeug klebriger, als erwartet. Ich frag Xanjo lieber, ob das 'n Problem is'.\n\nAber erst zu Eurer Lektion. Passt gut auf und lernt schnell.\n\n<Rana nimmt einen von Schuppen bedeckten Balg und zeigt Euch, wie man die Haut gründlicher entfernt, ohne dabei die Schuppen zu beschädigen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52216] = { id = 52216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexoskelett", description = "Ich hab mit Xanjo 'ne Wette darüber am Lauf'n, welches Leder 'ne Rüstung widerstandsfähiger gegen Hieb- und Stichangriffe macht.\n\nEr sagt, Schuppen, aber mir fällt da was Bess'res ein.\n\nWenn man das Exoskelett von 'nem Makrura richtig behandelt, sollte es robust wie 'ne normale Plattenrüstung sein.\n\nBringt mir den Panzer von 'nem Bittertidenmakrura, und ich bring Euch bei, wie Ihr leichter an die Knoch'n der Biester kommt, die Ihr häutet.", sourceObjective = "Beschafft einen intakten Makrurapanzer.", progress = "Habt Ihr den Panzer?", completion = "Nich' übel.\n\nDiese Platten sin' richtig dick und TECHNISCH geseh'n Leder. Damit hab ich so gut wie gewonn'.\n\nWas Eure Lektion angeht... Makrura ham leider keine Knoch'n.\n\n<Rana grinst.>\n\nSchon gut! Dann bring ich Euch eb'n was Nützliches bei!\n\n<Sie setzt den Panzer ab und zeigt Euch, wie man ertasten kann, ob ein Knochen gebrochen ist, bevor man ihn entfernt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52217] = { id = 52217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wahrhaft königlicher Loa", description = "He, {name}! Kommt ma' rüber. Psst. Kommt näher.\n\n<Rana senkt ihre Stimme zu einem Flüstern.>\n\nEs gibt da was, das Ihr für mich tun könntet. Unter Umständ'n könnte man's wohl als Frevel ausleg'n, aber... na ja...\n\nRezan war früher ma' der Loa der Könige, aber man hat ihn nach Atal'Dazar gebracht, un' sein Schicksal macht mich traurig.\n\nZieht los un' bringt mir einen seiner Knoch'n von dort mit. Es muss gar kein ganzer Knoch'n sein. 'n Splitter reicht, egal, wie klein er is'.\n\nTut das für mich, und ich zeig Euch alles, was ich über die Knochengewinnung beim Kürschnern weiß.", sourceObjective = "Beschafft Rezans Knochenfragment.", progress = "Habt Ihr's?", completion = "<Rana spricht mit gesenkter Stimme, während sie das Knochenfragment in einem kleinen Beutel verstaut, den sie um den Hals trägt.>\n\nDas bedeutet mir sehr viel.\n\nAuch wenn ich niemals 'ne Königin sein werde, wird der Loa der Könige für den Rest meiner Tage über mich wach'n.\n\n<Rana klopft sich den Staub von den Händen und spricht in ihrer üblichen Lautstärke weiter.>\n\nWenn ich mich recht entsinne, hab ich versproch'n, Euch alles zu lehren, was ich über's Sammeln von Knochen weiß, oder?\n\n<Rana beginnt, Euch zu erklären, welche Knochen sich leicht aus ihrer Verankerung lösen lassen, ohne dabei zu brechen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52218] = { id = 52218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtmahre", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[52219] = { id = 52219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Blutprinz Dreven", description = "Wir müssen Blutprinz Dreven und seine Anhänger töten. Ich weiß, wohin sie wollen. Unser Plan lautet folgendermaßen:\n\nIhr brecht mit Keeshan zu den Tunneln auf und sorgt dafür, dass Dreven sich in Sicherheit wiegt.\n\nIch werde kurz darauf mit den Schildwachen den Eingang versperren, und schon sitzen er und seine Verbündeten in der Falle.\n\nDann töten wir sie alle. Ich werde die anderen benachrichtigen und zum Aufbruch blasen.\n\nAuf geht's.", sourceObjective = "Trefft Euch mit Keeshan in den eingestürzten Tunneln in Nazmir.", completion = "Keeshan ist wieder auf den Beinen, und ich habe Späher ausgesandt, um die Leichname meiner Schildwachen zu suchen.\n\nSie sind im Kampf gegen ein Monster gefallen. Keeshan und ich werden ihnen eine ehrenvolle Bestattung bereiten.\n\nIch werde Halford einen Bericht über die Vorfälle hier zukommen lassen. Drevens Vernichtung muss ab jetzt höchste Priorität eingeräumt werden.\n\nHabt Dank für all Eure Hilfe, {name}. Ohne Euch hätten wir es niemals geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[52221] = { id = 52221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Steinfaustwache", description = "Eure Anhänger haben Euch einen Bericht über einen Angriff auf die Steinfaustwache geschickt.\n\nDarin wird erklärt, dass es ein schwer errungener Sieg war und dass alle bislang in dem Außenposten lebenden Banditen getötet wurden.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt den Bericht über Euren Sieg zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission zum Tiragardesund?", completion = "Die Mission, im Tiragardesund einen zusätzlichen Stützpunkt zu errichten, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch entsenden, damit Ihr den Bau der Befestigungsanlagen beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52222] = { id = 52222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinfaustwache", description = "Der Überfall, den Ihr auf die Steinfaustwache im Tiragardesund geplant habt, war erfolgreich. Gut gemacht.\n\nDer Außenposten ist bereit zur Übernahme.\n\nMacht Euch auf den Weg zur Steinfaustwache im Tiragardesund und baut dort Befestigungsanlagen.\n\nDie Steinfaustwache wird als Außenposten eine entscheidende Rolle in unserer Kampagne gegen die Allianz spielen.\n\nGeht mit Ehre!", sourceObjective = "Beansprucht die Steinfaustwache für die Horde.", completion = "Throm-Ka, {name}. Hier ist ein ausgezeichneter Platz für einen Außenposten! Dank Eurer Führung hat die Horde einen weiteren Stützpunkt im Tiragardesund!", sourceObjectiveStatus = "unverified-source-field" }
quests[52223] = { id = 52223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salzzwick", description = "He! {name}! Ich möchte Euch einen Handel vorschlagen.\n\nIn einem meiner liebsten Jagdgründe hat sich eine monströse Krabbe eingenistet.\n\nDank der Sirenen musste ich schon einen Teil meines Reviers aufgeben, und es kann nicht angehen, dass ich noch mehr an eine KRABBE verliere!\n\nBringt mir Salzzwicks Kopf! Im Gegenzug werde ich Euch zeigen, wie man beim Kürschnern noch mehr Leder gewinnt.\n\n<Karina hält kurz inne und überdenkt ihre Wortwahl.>\n\nNun ja, die meisten Kreaturen, die mir an den Kragen wollen, haben eben Köpfe... Bringt mir einfach irgendeinen Teil der Krabbe als Beweis für ihren Tod.", sourceObjective = "Erlegt Salzzwick und bringt Karina Düsterhimmel den \"Kopf\" der Krabbe.", progress = "Habt Ihr die Bestie schon erlegt?", completion = "Hervorragend! Das werde ich noch heute mit einer zünftigen Jagd feiern.\n\nUnd was Euch angeht, {name}, lasst mich Euch eine Technik demonstrieren, die Ihr wahrscheinlich noch nie zuvor gesehen habt...", sourceObjectiveStatus = "unverified-source-field" }
quests[52224] = { id = 52224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dolch mit Elfenbeingriff", description = "Beim Häuten der Bestie spürt Ihr einen Knoten in ihrem Magen.\n\nAls Ihr das genauer untersucht, findet Ihr einen Dolch mit einem exquisit gravierten Elfenbeingriff.\n\nWährend Ihr ihn vorsichtig herausholt, fragt Ihr Euch, ob Karina Düsterhimmel vielleicht etwas darüber wissen könnte.", sourceObjective = "Bringt den Dolch mit Elfenbeingriff zu Karina Düsterhimmel.\n\nBereitgestellter Gegenstand:", completion = "Ich hatte mich schon gefragt, was mit ihm passiert ist...\n\nJa, ich kenne diese Klinge. Sie gehörte meinem Mentor.\n\nWir kamen an Bord desselben Schiffes hierher, doch dann verschwand er. Er sprach immer davon, ein Haus in Drustvar mit Blick aufs Meer bauen zu wollen, also dachte ich, er sei dort.\n\nAber scheinbar hat ihn diese Bestie verschlungen... Ich bin froh, dass Ihr sie erlegt und so Rache für ihn geübt habt.\n\nAls Dank möchte ich Euch in sein Geheimnis der Kürschnerei einweihen.\n\n<Karina nimmt einen unbearbeiteten Pelz und beginnt, Euch die Technik ihres verschollenen Mentors zu demonstrieren.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52225] = { id = 52225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modeopfer", description = "Trotz meiner WIEDERHOLTEN Feststellung, dass ich keine Lederverarbeiterin bin, hat mich einer dieser dickleibigen Adligen dieser Stadt beauftragt, einen Gürtel aus \"feinstem Sauroliskenleder\" für ihn zu fertigen.\n\nAlso... werde ich einfach die Materialien besorgen, sie zusammen mit ein wenig Gold an Kassandra weitergeben, damit sie den Gürtel anfertigt, und den Rest des Goldes selbst einstreichen.\n\nFür Euch bedeutet das, dass Ihr genug Sauroliskenleder für einen Lord stattlichsten Umfangs beschaffen müsst.\n\nAls Dank für Eure Mühe werde ich mir die Häute anschauen und sehen, ob ich Euch ein paar Tipps geben kann, um mehr Leder zu gewinnen.", sourceObjective = "Erbeutet 3 makellose Sauroliskenhäute von Seichtwassersaurolisken in Drustvar.", progress = "Habt Ihr die Bälge?\n\nMein Auftraggeber wird langsam... penetrant.", completion = "<Karina nimmt die Häute in Augenschein.>\n\nAkzeptable Arbeit. Wir werden beim Beschneiden zwar etwas Material einbüßen, aber es sollte dennoch für den Leibesumfang unseres geschätzten und ehrenwerten Wohltäters reichen.\n\nAußerdem glaube ich jetzt zu wissen, woran es bei Euch hapert, wenn es um die Materialgewinnung von Schuppentieren geht. Zeigt mir mal, wie Ihr es gemacht habt.\n\n<Karina gibt Euch ein Messer und beobachtet genau Eure Handgriffe, während Ihr sie erläutert. Gelegentlich unterbricht sie Euch, um die Position Eurer Hände zu korrigieren und Euch zu versichern, dass es so beim nächsten Mal noch besser klappen wird.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52226] = { id = 52226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildkrötensuppe", description = "Ich kann nicht fassen, dass ich ständig hier in der Stadt festsitze!\n\nAber Ihr werdet mir doch sicher helfen, nicht?\n\nWisst Ihr, ich habe da von gewissen Schildkröten gehört, die in heißen Quellen leben.\n\nDas Interessante an ihnen ist, dass sich ein Teil des dort im Wasser vorkommenden Schwefels in ihren Schuppen ablagert und ihnen ungewöhnliche Muster verleiht.\n\nIch habe zu viel zu tun, um es selbst zu überprüfen, aber wenn Ihr mir ein paar ihrer Häute besorgt, lehre ich Euch bereitwillig alles, was ich über das Häuten schuppiger Kreaturen weiß.", sourceObjective = "Erbeutet 5 schwefelbefleckte Schildkrötenhäute von angereicherten Felspanzern.", progress = "Sagt bitte, dass Ihr die Häute habt!", completion = "Mann, die sind ja... nicht so überwältigend.\n\nSo wie man sie beschrieben hat, hätte ich zumindest etwas Schillerndes erwartet.\n\nStattdessen sind sie einfach nur gelb und stinken nach Fürzen.\n\nWie auch immer, Ihr habt mir einen weiteren Tag herausgeschunden, bevor ich hier endgültig den Verstand verliere.\n\n<Karina zückt geschwind ihr Messer und lässt es zwischen den Schuppen entlanggleiten.\n\nWenn Ihr ihrem Können auch nicht das Wasser reichen könnt, seid Ihr zuversichtlich, dass Ihr nach dieser Demonstration mehr Schuppen ernten werdet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52227] = { id = 52227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochennadel", description = "<Ihr seht, wie Karina Blut aus einer Wunde in ihrer Hand saugt.>\n\nHe, könnt Ihr mir einen Gefallen tun? Als ich eine Kampfwunde in diesem Balg zunähen wollte, ist meine letzte Knochennadel gebrochen. Also brauche ich eine neue.\n\nAn der Küste von Drustvar habe ich Stachelratten gesichtet. Ihre Stacheln dürften den Zweck erfüllen.\n\nBringt mir einen ohne Makel, und ich werde Euch zeigen, wie Ihr beim Häuten mehr Knochen gewinnt.\n\n<Karina schaut auf ihre Hand.>\n\nUnd jetzt entschuldigt mich bitte. Besser, ich suche einen Heiler auf, bevor sich die Wunde entzündet.", sourceObjective = "Beschafft einen makellosen Stachel.", progress = "Bei mir türmen sich die Aufträge, während ich auf eine neue Nadel warte.\n\nUnd, habt Ihr sie?", completion = "Mal sehen... glatt, robust, spitz... Au! Sehr spitz sogar!\n\nJa, der sollte den Zweck bestens erfüllen. Gute Arbeit!\n\n<Karina nimmt ein Balg und macht sich daran, ein weiteres Loch zu flicken, das von einer Kampfwunde zu stammen scheint. \n\nAls sie mit ihrer Arbeit zufrieden ist, wendet sie sich Euch zu, um zu erklären, wie man beim Häuten mehr Knochen gewinnt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52228] = { id = 52228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Eine unzerbrechliche Knochennadel", description = "He, {name}, sucht Ihr Arbeit?\n\nLaut Berichten der Allianz haben die Trolle einen toten Gott oder so etwas. Ich glaube, \"Rezan\" war der Name, drüben in Atal'Dazar.\n\nSeit mir neulich meine letzte Knochennadel gebrochen ist, ist mir der Gedanke gekommen, dass eine Nadel aus dem Knochen eines Gottes unzerstörbar sein müsste.\n\nIch möchte, dass Ihr loszieht und mir einen Knochen dieses Gottes besorgt. Oder zumindest ein Knochenstück, das groß genug ist, um ein Nadelöhr einzuschnitzen und es als Nadel zu verwenden.\n\nIm Gegenzug zeige ich Euch alles, was ich über die Gewinnung von Knochen weiß.", sourceObjective = "Reist nach Atal'Dazar und beschafft Rezans Knochenfragment.", progress = "Ich hoffe, das funktioniert. Wäre schön, wenn diese verdammte Nadel für den Rest meines Lebens reicht...\n\nHabt Ihr ihn?", completion = "Gut! Das ist die perfekte Größe für genau die Art von filigranen Arbeiten, die ständig die Nadeln brechen lassen.\n\nSeid Ihr bereit für Eure Lektion?\n\n<Karina demonstriert Euch in den nächsten Minuten, wie man Knochen, deren Gewinnung Ihr bislang als zu zeitaufwendig erachtet hättet, blitzschnell herauslöst und von Haut und Fleisch befreit.>", sourceObjectiveStatus = "unverified-source-field" }
quests[52229] = { id = 52229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saubäre Arbeit" }
quests[52230] = { id = 52230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlendes Kleingeld" }
quests[52234] = { id = 52234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteckt inmitten der Blätter", description = "Als die Horde angriff, habe ich getan, was ich konnte, um sie aufzuhalten. Aber ich weiß nicht, wie viele bereits eingefallen sind, bevor ich den Zugang versiegeln konnte. Diese Barriere wird sie zwar erst einmal beschäftigen, aber ihr Angriff ist damit nicht gestoppt.\n\n<Malfurion spitzt die Ohren.>\n\nHört Ihr das? Die Uralten rufen uns!\n\nWir müssen sie um jeden Preis beschützen, {name}! Sie sehen Dinge, die unseren Augen verborgen bleiben, und hören, was unseren Ohren entgeht.\n\nEinige meiner Druiden halten sich im Zwielichttal auf. Findet sie. Schickt sie zum Hain der Uralten. Ich werde die Barriere verstärken.", sourceObjective = "Findet 8 verborgene Druiden der Klaue.", completion = "Elune sei Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[52236] = { id = 52236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dorniges Problem" }
quests[52237] = { id = 52237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tiefenpfuhl: Ruheloser Schrecken" }
