quests[52239] = { id = 52239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlendes Kleingeld" }
quests[52240] = { id = 52240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gartenhain", description = "Verfluchte Goblins mit ihren widerwärtigen Höllenmaschinen!\n\nSie setzen einen Schredder ein, um unseren heiligen Wald zu entweihen.\n\nWir müssen dieses Ungetüm ausschalten!", sourceObjective = "Bezwingt den monströsen Schredder.", completion = "Gut gemacht. Die Bäume haben so viele Geschichten zu erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[52241] = { id = 52241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Paradies für gierige Goblins", description = "Die Zandalari halten so manches mächtige antike Artefakt hier auf der Insel verborgen, gut geschützt vor neugierigen Blicken.\n\nAber andere ihrer Schätze sind ein wenig... auffälliger.\n\nEs ist kaum ein Wunder, dass Handelsprinz Gallywix der Verlockung Atal'Dazars nicht zu widerstehen vermochte, wenn man bedenkt, dass die Stadt aus massivem Gold erbaut wurde.\n\nKommt mit, dann werden wir ihn gemeinsam zu Fall bringen.", sourceObjective = "Benutzt Magister Umbrics Leerenportal, um in Atal'Dazar zu ihm zu stoßen.", completion = "Gallywix hat keinen Respekt vor Kultur oder Geschichte. Nur vor Geld.", sourceObjectiveStatus = "unverified-source-field" }
quests[52242] = { id = 52242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Welle des Neuen", description = "<Onu brüllt vor Schmerz.>\n\nDie Störung ist jetzt noch gravierender. Ich spüre eine mächtige Kraft in unserer Mitte, die anders ist als alles, was ich je erlebt habe. Sie entspringt der Erde selbst.\n\nIhr und Delaryn Sommermond müsst dem auf den Grund gehen, {name}. Brecht auf zu jenem Ort am Meer, den Ihr Nazj'vel nennt.", sourceObjective = "Geht der Ursache von Onus Schmerzen auf den Grund.", completion = "Die Horde hat die Meistergleve eingenommen!\n\nWir dachten, dieses Leuchten an diesem Ort wäre Elunes Licht... aber es scheint das Azerit zu sein, nach dem die Horde so fieberhaft sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[52243] = { id = 52243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibstoff für die Verwüster" }
quests[52244] = { id = 52244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Bohrungen auf" }
quests[52245] = { id = 52245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Furbolgs", description = "Die Urtume der Wälder sind alle miteinander verbunden. Wir nehmen Störungen tief in unserem Wurzelwerk wahr.\n\nIch spüre sie jetzt, in diesem Moment, {name}... das Stampfen ihrer Schritte in der Ferne, den grollenden Donner des Krieges. Mit jedem Ast, der bricht, wecken sie die Urtume.\n\nSchon bald werden meine Brüder es ihnen auf ihre Art heimzahlen, denn das Gleichgewicht der Natur darf niemand stören.\n\nDoch eine Störung naht, und unsere Seelenverwandten rufen um Hilfe. Geht ihr auf den Grund und stellt das Gleichgewicht wieder her.", sourceObjective = "Findet jene, die im Bau der Schwarzfelle um Hilfe rufen.", completion = "Wurden die Furbolgs wieder ausgewildert?", sourceObjectiveStatus = "unverified-source-field" }
quests[52246] = { id = 52246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollene Fracht", description = "Ich ließ zu, dass die Trauer mein Urteil trübte, und Jaina hat womöglich schon den höchsten Preis für meinen Fehltritt zahlen müssen. Und doch habe ich noch Hoffnung, dass sie am Leben ist.\n\nIch weiß nicht, wohin man Jaina verschleppt hat, nachdem Aschenwinds Leute sie aus der Burg geführt haben. Die Aufzeichnungen in ihren Niederlassungen hier in Boralus werden Euch gewiss offenbaren, wo sie sie hingebracht haben.\n\n{name}, Ihr habt meinen Leuten geholfen, als ich es für unnötig hielt. Jetzt aber bitte ich Euch erneut um Hilfe. Rettet das Leben meiner Tochter!", sourceObjective = "Durchsucht die Aschenwindbüros nach Hinweisen, wohin Jaina verschleppt wurde.", progress = "Habt Ihr herausgefunden, was mit Jaina geschehen ist?", completion = "<Katherine schaut entschlossen auf.>\n\nAuch wenn wir nur wenige Hinweise haben, muss ich einfach glauben, dass sie noch lebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[52247] = { id = 52247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf Gallywix", description = "Seht Euch das an... Die Goblins plündern diese uralten Ornamente, als würden sie an einem Buffet das Essen horten. Was für eine Schande.\n\nAber wir können uns nicht um alles kümmern, was hier vor sich geht. Gallywix wird bald wissen, dass wir hier sind.\n\nLasst uns nicht zögern. Gehen wir diese Stufen hinauf und machen wir Gallywix ausfindig. Wir finden ihn mit Sicherheit dort, wo diese Diebe ihre ganzen Schätze hinbringen.\n\nOh, und seid bitte vorsichtig. Die Zandalari lassen Orte wie diesen normalerweise nicht unbewacht.", sourceObjective = "Spürt Handelsprinz Gallywix auf und jagt ihn.", completion = "Ein \"Lustschloss\"? Wie egoistisch muss man sein, um für so etwas das Leben und das Schicksal seiner Leute aufs Spiel zu setzen?", sourceObjectiveStatus = "unverified-source-field" }
quests[52248] = { id = 52248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Küsten von Xibala" }
